// GERADO por scripts/build-engine-bundle.mjs (roda no "npm run build"). Não edite: mude os arquivos de origem e gere de novo.
// Pacote do motor de testes dinâmico que a IDE grava em .metabuilder/testes/engine.
export const ENGINE_VERSION = "f60c00b7ab"
export const ENGINE_FILES: Record<string, string> = {
 "e2e/package.json": "{\n  \"name\": \"metabuilder-test-engine\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"description\": \"Motor de testes dinâmico do MetaBuilder PRO (instalado pela IDE; não editar)\",\n  \"devDependencies\": {\n    \"@playwright/test\": \"^1.49.0\",\n    \"bcryptjs\": \"^2.4.3\",\n    \"pg\": \"^8.13.0\"\n  }\n}\n",
 "e2e/playwright.dynamic.config.ts": "import { defineConfig } from '@playwright/test'\nimport path from 'node:path'\nimport fs from 'node:fs'\nimport { CONFIG } from './dynamic/lib/config'\n\n/**\n * Testes dinâmicos: gerados a partir do manifesto do projeto (o que o dev configurou no Studio), contra o app exportado (Node + Postgres).\n * A configuração vem de E2E_CONFIG (JSON gravado pela IDE) ou, no repositório, do e2e/.env.real. Rodar: npm run dyn:test  (E2E_MANIFEST=caminho.json para outro manifesto).\n */\nif (!fs.existsSync(path.join(CONFIG.appDir, 'package.json'))) {\n  throw new Error(`Não achei o app exportado em \"${CONFIG.appDir}\". Ejete o projeto (IDE > Ejetar para uma pasta) e escolha essa pasta no Ambiente de Testes.`)\n}\n\nexport default defineConfig({\n  testDir: './dynamic/tests',\n  timeout: 60_000,\n  expect: { timeout: 10_000 },\n  fullyParallel: false,\n  workers: 1,\n  retries: 0,\n  // o relator da IDE escreve uma linha por teste (começou/terminou) para o painel \"Ambiente de Testes\" mostrar o andamento ao vivo\n  reporter: [['list'], ['./dynamic/ide-reporter.ts'], ['html', { outputFolder: 'playwright-report-dynamic', open: 'never' }]],\n  outputDir: 'test-results-dynamic',\n  globalSetup: './dynamic/global-setup.ts',\n  globalTeardown: './dynamic/global-teardown.ts',\n  // E2E_HEADED=1 abre o navegador na tela (\"ver ao vivo\"); E2E_SLOWMO=<ms> espera entre as ações para dar tempo de acompanhar\n  use: { channel: (process.env.E2E_BROWSER || 'chrome') as 'chrome' | 'msedge', headless: process.env.E2E_HEADED !== '1', launchOptions: { slowMo: Number(process.env.E2E_SLOWMO || 0), args: process.env.E2E_HEADED === '1' ? ['--start-maximized'] : [] }, trace: 'retain-on-failure', screenshot: 'only-on-failure', locale: 'pt-BR', baseURL: `http://localhost:${CONFIG.port}` },\n  projects: [{ name: 'dynamic-pg-node' }],\n  webServer: {\n    command: `npx next start -p ${CONFIG.port}`,\n    cwd: CONFIG.appDir,\n    url: `http://localhost:${CONFIG.port}/login`,\n    reuseExistingServer: false,\n    timeout: 90_000,\n    // com a configuração da IDE (E2E_CONFIG) o app sobe apontando para o banco de TESTE: DATABASE_URL do ambiente vale mais que o do .env.local\n    env: { EXPORT_DIR: CONFIG.exportDir, ...(process.env.E2E_CONFIG ? { DATABASE_URL: CONFIG.dbUrl } : {}) },\n  },\n})\n",
 "e2e/dynamic/ide-reporter.ts": "import type { FullResult, Reporter, TestCase, TestResult } from '@playwright/test/reporter'\nimport { eventLine, statusFromPlaywright, type TestEvent } from '../../src/lib/testing/results'\n\n/**\n * Relator para o painel \"Ambiente de Testes\" da IDE: escreve uma linha por evento (começou / terminou / acabou) na saída, em JSON, depois do prefixo\n * @@MB@@. O painel lê a saída, separa estas linhas e atualiza a tela ao vivo. Não substitui o relatório HTML: roda ao lado dele.\n */\nexport default class IdeReporter implements Reporter {\n  private total = 0\n  private passed = 0\n  private failed = 0\n  private skipped = 0\n\n  // o grupo é o \"describe\" (caso de uso) e o título é o do teste: os dois últimos itens do caminho (projeto, arquivo, grupo, teste)\n  private names(test: TestCase) {\n    const p = test.titlePath()\n    return { group: p[p.length - 2] ?? '', title: p[p.length - 1] ?? '' }\n  }\n\n  private emit(ev: TestEvent) { process.stdout.write(eventLine(ev) + '\\n') }\n\n  onTestBegin(test: TestCase) {\n    this.emit({ t: 'begin', ...this.names(test) })\n  }\n\n  onTestEnd(test: TestCase, result: TestResult) {\n    const status = statusFromPlaywright(result.status)\n    this.total++\n    if (status === 'passed') this.passed++\n    else if (status === 'skipped') this.skipped++\n    else this.failed++\n    const message = result.error?.message ?? ''\n    // sem os códigos de cor do terminal, e só o começo: o relatório HTML tem o resto\n    const error = message ? message.replace(/\\u001b\\[[0-9;]*m/g, '').split('\\n').slice(0, 6).join('\\n') : undefined\n    const anexo = (nome: string) => result.attachments.find(a => a.name === nome)?.body?.toString()\n    const shot = anexo('mb-shot')\n    const video = anexo('mb-video')\n    this.emit({ t: 'end', ...this.names(test), status, ms: result.duration, ...(error ? { error } : {}), ...(shot ? { shot } : {}), ...(video ? { video } : {}) })\n  }\n\n  onEnd(_result: FullResult) {\n    this.emit({ t: 'done', total: this.total, passed: this.passed, failed: this.failed, skipped: this.skipped })\n  }\n}\n",
 "e2e/dynamic/make-pdf.mjs": "// Gera um PDF a partir do HTML do relatório de testes (usado pelo botão Download > PDF do painel da IDE).\n// Uso: node dynamic/make-pdf.mjs <relatorio.html> <saida.pdf>\nimport { chromium } from '@playwright/test'\nimport path from 'node:path'\nimport { pathToFileURL } from 'node:url'\n\nconst [html, pdf] = process.argv.slice(2)\nif (!html || !pdf) {\n  console.error('Uso: node dynamic/make-pdf.mjs <relatorio.html> <saida.pdf>')\n  process.exit(2)\n}\n\nconst browser = await chromium.launch({ channel: process.env.E2E_BROWSER || 'chrome' })\ntry {\n  const page = await browser.newPage()\n  await page.goto(pathToFileURL(path.resolve(html)).href)\n  await page.emulateMedia({ media: 'print' })\n  await page.pdf({ path: path.resolve(pdf), format: 'A4', printBackground: true, margin: { top: '14mm', bottom: '14mm', left: '12mm', right: '12mm' } })\n} finally {\n  await browser.close()\n}\n",
 "e2e/dynamic/prepare-app.mjs": "// Prepara o app exportado para o teste: instala as dependências (se faltarem) e compila (se nunca foi compilado ou se o código mudou depois da última compilação).\n// Uso: node dynamic/prepare-app.mjs   (a pasta do app vem de E2E_CONFIG ou de E2E_REAL_APP_DIR)\nimport { spawnSync } from 'node:child_process'\nimport fs from 'node:fs'\nimport path from 'node:path'\n\nconst cfg = process.env.E2E_CONFIG && fs.existsSync(process.env.E2E_CONFIG) ? JSON.parse(fs.readFileSync(process.env.E2E_CONFIG, 'utf8')) : {}\nconst appDir = cfg.appDir || process.env.E2E_REAL_APP_DIR\nif (!appDir || !fs.existsSync(path.join(appDir, 'package.json'))) {\n  console.error(`Não achei o app exportado em \"${appDir}\".`)\n  process.exit(1)\n}\n\nconst run = (cmd, args) => {\n  const r = spawnSync(cmd, args, { cwd: appDir, stdio: 'inherit', shell: true, env: { ...process.env, ...(cfg.dbUrl ? { DATABASE_URL: cfg.dbUrl } : {}) } })\n  if (r.status !== 0) { console.error(`Falhou: ${cmd} ${args.join(' ')}`); process.exit(r.status || 1) }\n}\n\n/** Data da última alteração do código do app (ignora dependências e a própria compilação). */\nfunction ultimaAlteracao(dir, ignorar = new Set(['node_modules', '.next', '.git', 'db'])) {\n  let max = 0\n  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n    if (ignorar.has(e.name)) continue\n    const p = path.join(dir, e.name)\n    if (!e.isDirectory() && /\\.(md|log)$/i.test(e.name)) continue\n    max = Math.max(max, e.isDirectory() ? ultimaAlteracao(p, ignorar) : fs.statSync(p).mtimeMs)\n  }\n  return max\n}\n\nif (!fs.existsSync(path.join(appDir, 'node_modules'))) {\n  console.log('Preparando o app de teste: instalando as dependências (só na primeira vez, pode levar alguns minutos)...')\n  run('npm', ['install', '--no-audit', '--no-fund'])\n}\nconst marca = path.join(appDir, '.next', 'BUILD_ID')\nif (!fs.existsSync(marca) || ultimaAlteracao(appDir) > fs.statSync(marca).mtimeMs) {\n  console.log('Preparando o app de teste: compilando (next build)...')\n  run('npx', ['next', 'build'])\n} else {\n  console.log('App de teste já está compilado e atualizado.')\n}\n",
 "e2e/dynamic/db-tool.mjs": "// Ferramenta de banco do motor de testes (a IDE a chama): testa a conexão com o banco de teste, cria o usuário de teste do app e o remove.\n//   node dynamic/db-tool.mjs check     -> conecta e confere se as tabelas dos casos de uso existem\n//   node dynamic/db-tool.mjs prepare   -> cria o usuário de teste (ou renova a senha dele), com a senha gerada, e o põe no grupo de administração, se houver\n//   node dynamic/db-tool.mjs copy      -> cria, no mesmo servidor, uma cópia do banco (CREATE DATABASE ... TEMPLATE); dbUrl = banco de origem, copyName = nome da cópia\n//   node dynamic/db-tool.mjs remove    -> remove o usuário de teste e o vínculo dele com o grupo\n// Entrada: E2E_CONFIG (JSON com dbUrl e, opcionalmente, robotPassword) e E2E_MANIFEST (manifesto com a configuração de login). Saída: uma linha @@MB-DB@@{json}.\nimport crypto from 'node:crypto'\nimport fs from 'node:fs'\nimport pg from 'pg'\nimport { colocarNoGrupo, grupoAdmin, upsertUsuario } from './lib/acesso.mjs'\n\nconst MARCA = '@@MB-DB@@'\nconst ROBO_EMAIL = 'e2e_motor@metabuilder.local'\nconst ROBO_NOME = 'E2E Motor (testes automáticos)'\nconst IDENT = /^[a-zA-Z_][a-zA-Z0-9_]*$/\n\nconst out = o => { console.log(MARCA + JSON.stringify(o)); process.exit(o.ok ? 0 : 1) }\nconst cfg = JSON.parse(fs.readFileSync(process.env.E2E_CONFIG, 'utf8'))\nconst manifest = process.env.E2E_MANIFEST && fs.existsSync(process.env.E2E_MANIFEST) ? JSON.parse(fs.readFileSync(process.env.E2E_MANIFEST, 'utf8')) : null\nconst action = process.argv[2]\nconst limpar = msg => String(msg || '').replace(/(:\\/\\/[^:@/]+:)[^@]+@/g, '$1***@')\nconst id = n => { if (!IDENT.test(String(n))) throw new Error(`nome inválido: ${n}`); return `\"${n}\"` }\n\nif (action === 'copy') {\n  // a cópia é feita por quem NÃO está conectado ao banco de origem (o Postgres não deixa copiar um banco em uso), por isso antes de abrir a conexão principal\n  const origem = decodeURIComponent(new URL(cfg.dbUrl).pathname.slice(1))\n  const nome = String(cfg.copyName || '').trim()\n  if (!/^[a-z_][a-z0-9_]{0,62}$/.test(nome)) out({ ok: false, error: 'Nome inválido para a cópia: use letras minúsculas, números e _ (começando por letra).' })\n  if (nome === origem) out({ ok: false, error: 'A cópia precisa ter um nome diferente do banco original.' })\n  const adm = new URL(cfg.dbUrl); adm.pathname = '/postgres'\n  const a = new pg.Client({ connectionString: adm.toString(), connectionTimeoutMillis: 8000 })\n  try { await a.connect() } catch (e) { out({ ok: false, error: limpar(e.message) }) }\n  try {\n    if ((await a.query('select 1 from pg_database where datname = $1', [nome])).rowCount > 0) out({ ok: true, existed: true, name: nome })\n    const tam = Number((await a.query('select pg_database_size($1) as s', [origem])).rows[0].s)\n    await a.query(`create database \"${nome}\" template \"${origem.replace(/\"/g, '\"\"')}\"`)\n    out({ ok: true, name: nome, sizeMb: Math.round(tam / 1048576) })\n  } catch (e) {\n    const porCodigo = { '55006': 'O banco original está em uso por outro programa (o app, DBeaver...). Feche as conexões com ele e tente de novo, ou use o script para o administrador.', '42501': 'O usuário do banco não tem permissão para criar bancos (CREATEDB). Peça ao administrador do banco ou use o script.' }\n    out({ ok: false, error: porCodigo[e.code] || limpar(e.message) })\n  }\n}\n\nconst c = new pg.Client({ connectionString: cfg.dbUrl, connectionTimeoutMillis: 8000 })\ntry {\n  await c.connect()\n} catch (e) {\n  out({ ok: false, error: limpar(e.message) })\n}\n\ntry {\n  if (action === 'check') {\n    const versao = (await c.query('select version() as v, current_database() as d, pg_size_pretty(pg_database_size(current_database())) as sz')).rows[0]\n    const esperadas = manifest ? [...new Set(manifest.views.flatMap(v => [v.table, ...v.details.map(d => d.table)]).filter(Boolean))] : []\n    const achadas = new Set((await c.query(\"select table_name from information_schema.tables where table_schema not in ('pg_catalog','information_schema')\")).rows.map(r => r.table_name))\n    const faltam = esperadas.filter(t => !achadas.has(t))\n    out({ ok: true, database: versao.d, size: versao.sz, version: String(versao.v).split(' ').slice(0, 2).join(' '), tables: { expected: esperadas.length, missing: faltam }, authType: manifest?.auth?.type ?? null })\n  }\n\n  const auth = manifest?.auth\n  if (!auth || auth.type === 'none') out({ ok: true, noAuth: true })\n  if (auth.type !== 'database') out({ ok: false, error: `O login do tipo \"${auth.type}\" ainda não é suportado pelos testes automáticos.` })\n  const { usersTable, emailColumn, passwordColumn } = auth\n  if (!usersTable || !emailColumn || !passwordColumn) out({ ok: false, error: 'A configuração de login do projeto não informa a tabela de usuários e as colunas de e-mail e senha.' })\n\n  const pkUser = auth.usersPk || 'id'\n  const link = auth.access?.link\n  const achar = async () => (await c.query(`select ${id(pkUser)}::text as id from ${id(usersTable)} where ${id(emailColumn)} = $1`, [ROBO_EMAIL])).rows[0]?.id\n\n  if (action === 'remove') {\n    const uid = await achar()\n    if (uid && link?.kind === 'table') await c.query(`delete from ${id(link.table)} where ${id(link.userColumn)}::text = $1`, [uid])\n    if (uid) await c.query(`delete from ${id(usersTable)} where ${id(pkUser)}::text = $1`, [uid])\n    out({ ok: true, removed: !!uid })\n  }\n\n  if (action === 'prepare') {\n    const senha = cfg.robotPassword || crypto.randomBytes(18).toString('base64url')\n    const formato = String(auth.hash || 'bcrypt').toLowerCase()\n    const colunas = (await c.query(\"select column_name from information_schema.columns where table_schema = current_schema() and table_name = $1\", [usersTable])).rows.map(r => r.column_name)\n    if (colunas.length === 0) out({ ok: false, error: `A tabela de usuários \"${usersTable}\" não existe no banco de teste.` })\n    if (!colunas.includes(emailColumn) || !colunas.includes(passwordColumn)) out({ ok: false, error: `A tabela \"${usersTable}\" não tem as colunas ${emailColumn} e ${passwordColumn}.` })\n\n    const { id: uid, criado } = await upsertUsuario(c, auth, { email: ROBO_EMAIL, nome: ROBO_NOME, senha })\n\n    // gestão de acesso: coloca o usuário no grupo de administração, se o projeto tiver um (não cria grupo nenhum)\n    let grupo = null\n    const admin = uid ? await grupoAdmin(c, auth) : null\n    if (admin) { grupo = admin.nome; await colocarNoGrupo(c, auth, uid, admin.id) }\n    out({ ok: true, user: ROBO_EMAIL, password: senha, created: criado, group: grupo, hash: formato })\n  }\n\n  out({ ok: false, error: `ação desconhecida: ${action}` })\n} catch (e) {\n  out({ ok: false, error: limpar(e.message) })\n} finally {\n  await c.end().catch(() => {})\n}\n",
 "e2e/dynamic/global-setup.ts": "import fs from 'node:fs'\nimport path from 'node:path'\nimport { limparSegurancaDoBanco } from './lib/seguranca'\nimport { alvosDeLimpeza, arquivoBase, assertSeguro, impressaoDigital, limparSobras, tabelasDoManifesto } from './lib/guard'\nimport type { TestManifest } from '../../src/lib/testing/manifestTypes'\n\n/** Antes da rodada: confere que o banco é o de teste e guarda a impressão digital das tabelas dos casos de uso. */\nexport default async function globalSetup() {\n  assertSeguro()\n  const manifesto = process.env.E2E_MANIFEST || path.join(import.meta.dirname, 'manifests', 'vendas-pg.sample.json')\n  const m = JSON.parse(fs.readFileSync(manifesto, 'utf8')) as TestManifest\n  const tabelas = tabelasDoManifesto(m)\n  // teste de integração: sobras de uma rodada anterior interrompida saem antes de guardar a impressão digital (a rodada começa limpa)\n  const tipos = (process.env.E2E_TYPES || '').split(',')\n  const gravaDados = tipos.includes('integracao') || tipos.includes('seguranca')\n  const limpeza = gravaDados ? alvosDeLimpeza(m) : []\n  if (limpeza.length > 0) await limparSobras(limpeza)\n  const seguranca = tipos.includes('seguranca') ? m.auth ?? null : null\n  if (seguranca) await limparSegurancaDoBanco(seguranca) // usuários e grupos temporários de uma rodada interrompida\n  fs.mkdirSync(path.dirname(arquivoBase()), { recursive: true })\n  fs.writeFileSync(arquivoBase(), JSON.stringify({ tabelas, limpeza, seguranca, antes: await impressaoDigital(tabelas) }))\n}\n",
 "e2e/dynamic/global-teardown.ts": "import fs from 'node:fs'\nimport { limparSegurancaDoBanco } from './lib/seguranca'\nimport { arquivoBase, diferencas, impressaoDigital, limparSobras, type Impressao } from './lib/guard'\n\n/** Depois da rodada: a impressão digital das tabelas tem de ser a mesma do início; senão a rodada falha e avisa. */\nexport default async function globalTeardown() {\n  if (!fs.existsSync(arquivoBase())) return\n  const { tabelas, antes, limpeza = [], seguranca } = JSON.parse(fs.readFileSync(arquivoBase(), 'utf8')) as { tabelas: string[]; antes: Impressao; limpeza?: Array<{ tabela: string; coluna: string }>; seguranca?: any }\n  if (limpeza.length > 0) await limparSobras(limpeza) // o que um teste de integração deixou para trás sai antes da conferência\n  if (seguranca) await limparSegurancaDoBanco(seguranca) // e os usuários e grupos temporários dos testes de segurança\n  const difs = diferencas(antes, await impressaoDigital(tabelas))\n  if (difs.length > 0) {\n    throw new Error(`ATENÇÃO: os dados do banco mudaram durante a rodada (${difs.join('; ')}). Confira o banco de teste antes de rodar de novo.`)\n  }\n  console.log(`\\nBanco intacto: ${tabelas.length} tabela(s) dos casos de uso continuam exatamente como estavam (quantidade e conteúdo conferidos).`)\n}\n",
 "e2e/dynamic/lib/config.ts": "import fs from 'node:fs'\nimport path from 'node:path'\n\n/**\n * Configuração do motor de testes dinâmico. Duas origens:\n *  - E2E_CONFIG = caminho de um JSON (é o que a IDE grava para o motor instalado na pasta do usuário);\n *  - sem ela, o modo do repositório: variáveis E2E_REAL_* e o arquivo e2e/.env.real (criado por `npm run real:robot`).\n */\nexport interface EngineConfig {\n  /** pasta do app exportado a testar (a que tem package.json e .env.local) */\n  appDir: string\n  port: number\n  /** conexão com o banco de TESTE (o mesmo que o app exportado usa): é nele que o motor confere que nada foi alterado */\n  dbUrl: string\n  /** usuário do app que o robô usa para entrar */\n  user: string\n  password: string\n  /** copy = uma cópia do banco que o cliente informou (padrão) · original = o banco do próprio app, só com o consentimento do cliente */\n  mode: 'copy' | 'original'\n  /** o cliente confirmou na IDE que o banco informado é uma cópia de teste (modo copy) */\n  copyConfirmed: boolean\n  /** o cliente consentiu na IDE em rodar no banco original (modo original) */\n  consentOriginal: boolean\n  /** app sem login: o robô não entra */\n  noAuth: boolean\n  /** permite banco que não é desta máquina (só com o consentimento do cliente, dado na IDE) */\n  allowRemote: boolean\n  /** bancos permitidos; vazio = o próprio banco de dbUrl */\n  allowedDbs: string[]\n  /** pasta onde o app grava as exportações durante o teste */\n  exportDir: string\n}\n\nconst engineRoot = path.join(import.meta.dirname, '..', '..')\n\nfunction parseEnv(file: string): Record<string, string> {\n  const out: Record<string, string> = {}\n  if (!fs.existsSync(file)) return out\n  for (const line of fs.readFileSync(file, 'utf8').split(/\\r?\\n/)) {\n    if (!line.includes('=') || line.startsWith('#')) continue\n    out[line.slice(0, line.indexOf('='))] = line.slice(line.indexOf('=') + 1)\n  }\n  return out\n}\n\nexport function loadConfig(): EngineConfig {\n  const exportDir = path.join(engineRoot, '.apps', 'exports-dynamic')\n  const file = process.env.E2E_CONFIG\n  if (file) {\n    const j = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<EngineConfig>\n    return { appDir: '', port: 3102, dbUrl: '', user: '', password: '', mode: 'copy', copyConfirmed: false, consentOriginal: false, noAuth: false, allowRemote: false, allowedDbs: [], exportDir, ...j }\n  }\n  const env = parseEnv(path.join(engineRoot, '.env.real'))\n  const val = (k: string, d = '') => process.env[k] ?? env[k] ?? d\n  return {\n    appDir: val('E2E_REAL_APP_DIR', ''),\n    port: Number(val('E2E_REAL_PORT', '3102')),\n    dbUrl: val('E2E_REAL_PG_URL'),\n    user: val('E2E_REAL_USER'),\n    password: val('E2E_REAL_PASSWORD'),\n    mode: 'original',\n    copyConfirmed: false,\n    consentOriginal: true, // modo do repositório: o dev usa o próprio banco de desenvolvimento, com as travas antigas (lista de bancos permitidos, só local)\n    noAuth: false,\n    allowRemote: false,\n    allowedDbs: val('E2E_REAL_ALLOWED_DBS', 'crm').split(',').map(s => s.trim()).filter(Boolean),\n    exportDir,\n  }\n}\n\nexport const CONFIG = loadConfig()\n",
 "e2e/dynamic/lib/db.ts": "import pg from 'pg'\nimport { CONFIG } from './config'\n\n/** Consulta o banco de teste (uma conexão por consulta: simples e sem estado). Só as regras de leitura e a trava de segurança usam isto. */\nexport async function consultar<T = any>(sql: string, params: unknown[] = []): Promise<T[]> {\n  const c = new pg.Client({ connectionString: CONFIG.dbUrl })\n  await c.connect()\n  try { return (await c.query(sql, params)).rows as T[] } finally { await c.end() }\n}\n",
 "e2e/dynamic/lib/guard.ts": "import fs from 'node:fs'\nimport path from 'node:path'\nimport { CONFIG } from './config'\nimport { consultar } from './db'\nimport type { TestManifest } from '../../../src/lib/testing/manifestTypes'\nimport { campoMarcador, PREFIXO_E2E } from '../../../src/lib/testing/plan'\n\n/**\n * Trava de segurança do motor dinâmico, para qualquer projeto (não conhece tabelas de antemão):\n *  1. antes de começar: o banco de teste tem de ser uma cópia que o cliente confirmou, ou o banco original com o consentimento dele; o motor injeta esta conexão no app (DATABASE_URL), então o app e a conferência usam o mesmo banco;\n *  2. durante: o motor só lê; a única regra que poderia gravar (salvar o formulário vazio) apaga o que criou e falha;\n *  3. no fim: a \"impressão digital\" de cada tabela dos casos de uso (quantidade de linhas e um resumo de todo o conteúdo) tem de ser a mesma do início.\n */\n\nconst LOCAIS = ['localhost', '127.0.0.1', '::1']\nconst IDENT = /^[a-zA-Z_][a-zA-Z0-9_]*$/\nconst LIMITE_RESUMO = 200_000\n\nconst dbOf = (url: string) => { const u = new URL(url); return { host: u.hostname, db: u.pathname.replace(/^\\//, '') } }\n\n/** DATABASE_URL do .env.local do app exportado. */\nfunction bancoDoApp(): string {\n  const f = path.join(CONFIG.appDir, '.env.local')\n  if (!fs.existsSync(f)) throw new Error(`Não achei ${f}. Ejete o projeto para a pasta do app e tente de novo.`)\n  const m = /^DATABASE_URL\\s*=\\s*\"?([^\"\\r\\n]+)\"?/m.exec(fs.readFileSync(f, 'utf8'))\n  if (!m) throw new Error('DATABASE_URL não encontrado no .env.local do app exportado.')\n  return m[1]\n}\n\nexport function assertSeguro() {\n  if (!CONFIG.appDir || !fs.existsSync(path.join(CONFIG.appDir, 'package.json'))) throw new Error(`Não achei o app exportado em \"${CONFIG.appDir}\".`)\n  if (!CONFIG.dbUrl) throw new Error('Falta a conexão com o banco de teste (dbUrl).')\n  if (!CONFIG.noAuth && (!CONFIG.user || !CONFIG.password)) throw new Error('Falta o usuário de teste do app (a IDE o cria no banco de teste).')\n  const teste = dbOf(CONFIG.dbUrl)\n  if (CONFIG.mode === 'copy') {\n    // cópia informada pelo cliente: pode estar em qualquer lugar, mas só vale se ele confirmou que é uma cópia (o motor injeta esta conexão no app)\n    if (!CONFIG.copyConfirmed) throw new Error('Recusado: falta a confirmação de que o banco informado é uma cópia de teste (não o banco de produção).')\n  } else {\n    // banco original do app: só com o consentimento do cliente (ou, no repositório, na lista de bancos permitidos e local)\n    if (!CONFIG.consentOriginal) throw new Error('Recusado: rodar no banco original do app exige o consentimento do cliente, dado na IDE.')\n    const app = dbOf(bancoDoApp())\n    if (teste.host !== app.host || teste.db !== app.db) {\n      throw new Error(`Recusado: o app exportado usa o banco \"${app.db}\" em ${app.host}, mas o banco de teste configurado é \"${teste.db}\" em ${teste.host}. Eles precisam ser o mesmo.`)\n    }\n    if (!CONFIG.allowRemote && !LOCAIS.includes(teste.host)) throw new Error(`Recusado: o banco de teste está em ${teste.host}, que não é esta máquina, e não há consentimento do cliente para banco remoto.`)\n  }\n  const permitidos = CONFIG.allowedDbs.length > 0 ? CONFIG.allowedDbs : [teste.db]\n  if (!permitidos.includes(teste.db)) throw new Error(`Recusado: o banco \"${teste.db}\" está fora da lista permitida (${permitidos.join(', ')}).`)\n}\n\n/** Tabelas que os casos de uso leem ou gravam (a do caso de uso, as abas de detalhe e os subdetalhes). */\nexport function tabelasDoManifesto(m: TestManifest): string[] {\n  const set = new Set<string>()\n  for (const v of m.views) {\n    if (v.table) set.add(v.table)\n    for (const d of v.details) { set.add(d.table); for (const s of d.subDetails) set.add(s.table) }\n  }\n  return [...set].filter(t => IDENT.test(t)).sort()\n}\n\nexport type Impressao = Record<string, { linhas: number; resumo: string }>\n\n/** Quantidade de linhas e um resumo (md5) de todo o conteúdo de cada tabela; em tabelas enormes, só a quantidade. */\nexport async function impressaoDigital(tabelas: string[]): Promise<Impressao> {\n  const out: Impressao = {}\n  for (const t of tabelas) {\n    const [r] = await consultar(`select count(*)::int as n from \"${t}\"`).catch(() => [{ n: -1 }])\n    if (r.n < 0) { out[t] = { linhas: -1, resumo: 'tabela inexistente' }; continue }\n    let resumo = ''\n    if (r.n <= LIMITE_RESUMO) resumo = String((await consultar(`select coalesce(md5(string_agg(x::text, ',' order by x::text)), '') as h from \"${t}\" x`))[0].h)\n    out[t] = { linhas: r.n, resumo }\n  }\n  return out\n}\n\nexport function diferencas(antes: Impressao, depois: Impressao): string[] {\n  const difs: string[] = []\n  for (const t of Object.keys(antes)) {\n    const a = antes[t], d = depois[t]\n    if (a.linhas !== d?.linhas) difs.push(`${t}: ${a.linhas} → ${d?.linhas} linhas`)\n    else if (a.resumo !== d?.resumo) difs.push(`${t}: o conteúdo de linhas existentes foi alterado`)\n  }\n  return difs\n}\n\nexport const arquivoBase = (): string => path.join(import.meta.dirname, '..', '..', 'test-results-dynamic', 'baseline.json')\n\n/** Onde o teste de integração pode ter deixado linhas: (tabela, coluna de identificação) dos casos de uso Pesquisa + Cadastro. */\nexport function alvosDeLimpeza(m: TestManifest): Array<{ tabela: string; coluna: string }> {\n  const out: Array<{ tabela: string; coluna: string }> = []\n  for (const v of m.views) {\n    const c = v.logicType === 'pesquisa_cadastro' ? campoMarcador(v) : undefined\n    if (c && IDENT.test(v.table) && IDENT.test(c.column) && !out.some(o => o.tabela === v.table && o.coluna === c.column)) out.push({ tabela: v.table, coluna: c.column })\n  }\n  return out\n}\n\n/**\n * Apaga as linhas geradas pelo teste de integração (texto que começa com \"E2E-\" na coluna de identificação): sobras de uma rodada interrompida ou de uma falha no meio.\n * Dá algumas passadas porque uma linha pode depender de outra (chave estrangeira): o erro da primeira tentativa some quando a dependente já foi apagada.\n */\nexport async function limparSobras(alvos: Array<{ tabela: string; coluna: string }>) {\n  for (let passada = 0; passada < 3; passada++) {\n    for (const { tabela, coluna } of alvos) {\n      await consultar(`delete from \"${tabela}\" where \"${coluna}\"::text like $1`, [PREFIXO_E2E + '%']).catch(() => {})\n    }\n  }\n}\n",
 "e2e/dynamic/lib/acesso.mjs": "// Usuários, grupos e permissões de teste no banco de teste, para QUALQUER projeto: tabelas e colunas vêm da configuração de login do manifesto (auth).\n// Usado pela ferramenta de banco (db-tool.mjs) e pelos testes de segurança. Só mexe no que cria: usuários e_mail e2e_*, grupos E2E-Perm*, e as linhas deles.\nimport crypto from 'node:crypto'\nimport bcrypt from 'bcryptjs'\n\nconst IDENT = /^[a-zA-Z_][a-zA-Z0-9_]*$/\nexport const id = n => { if (!IDENT.test(String(n))) throw new Error(`nome inválido: ${n}`); return `\"${n}\"` }\nconst q = s => `'${String(s).replace(/'/g, \"''\")}'`\n\nexport const EMAIL_SEG = 'e2e_seg_%@metabuilder.local'\nexport const GRUPO_SEG = 'E2E-Perm%'\n\nexport function hashSenha(formato, senha) {\n  const f = String(formato || 'bcrypt').toLowerCase()\n  return f === 'bcrypt' ? bcrypt.hashSync(senha, 10)\n    : f === 'md5' ? crypto.createHash('md5').update(senha).digest('hex')\n    : f === 'sha256' ? crypto.createHash('sha256').update(senha).digest('hex')\n    : senha\n}\n\n/** Colunas da tabela (nome, tipo, se aceita nulo, se tem valor padrão). */\nasync function colunas(c, tabela) {\n  return (await c.query(\"select column_name, data_type, is_nullable, column_default from information_schema.columns where table_schema = current_schema() and table_name = $1\", [tabela])).rows\n}\n\n/** Valor SQL para uma coluna obrigatória que o teste não conhece: o mínimo que a faz aceitar a linha. */\nfunction valorPadrao(col, ehChave, rotulo) {\n  const t = col.data_type\n  if (ehChave && /char|text/.test(t)) return q(`e2e-${crypto.randomBytes(6).toString('hex')}`)\n  if (t === 'boolean') return 'true'\n  if (t === 'uuid') return 'gen_random_uuid()'\n  if (/timestamp|date|time/.test(t)) return 'now()'\n  if (/int|numeric|decimal|real|double/.test(t)) return '0'\n  if (/json/.test(t)) return \"'{}'\"\n  return q(rotulo)\n}\n\n/** Insere uma linha informando só o que se sabe (`dados`: coluna → valor) e completando as colunas obrigatórias sem valor padrão. Devolve a chave primária (texto). */\nasync function inserir(c, tabela, pk, dados, rotulo) {\n  const cols = await colunas(c, tabela)\n  if (cols.length === 0) throw new Error(`A tabela \"${tabela}\" não existe no banco de teste.`)\n  const nomes = [], exprs = [], params = []\n  const usadas = new Set(Object.keys(dados))\n  for (const [col, v] of Object.entries(dados)) { nomes.push(id(col)); exprs.push(`$${params.push(v)}`) }\n  for (const col of cols) {\n    if (usadas.has(col.column_name)) continue\n    const ativo = ['ativo', 'active', 'enabled'].includes(col.column_name) && col.data_type === 'boolean'\n    const obrigatoria = col.is_nullable === 'NO' && col.column_default == null\n    if (!ativo && !obrigatoria) continue\n    nomes.push(id(col.column_name)); exprs.push(ativo ? 'true' : valorPadrao(col, col.column_name === pk, rotulo))\n  }\n  const r = await c.query(`insert into ${id(tabela)} (${nomes.join(', ')}) values (${exprs.join(', ')}) returning ${id(pk)}::text as pk`, params)\n  return r.rows[0].pk\n}\n\nconst usuarioPor = async (c, auth, email) => (await c.query(`select ${id(auth.usersPk || 'id')}::text as id from ${id(auth.usersTable)} where ${id(auth.emailColumn)} = $1`, [email])).rows[0]?.id\n\n/** Cria o usuário (ou renova a senha do que já existe). Devolve { id, criado }. */\nexport async function upsertUsuario(c, auth, { email, nome, senha }) {\n  const hash = hashSenha(auth.hash, senha)\n  const pkU = auth.usersPk || 'id'\n  let uid = await usuarioPor(c, auth, email)\n  if (uid) {\n    const cols = await colunas(c, auth.usersTable)\n    const sets = [`${id(auth.passwordColumn)} = $1`]\n    for (const n of ['ativo', 'active', 'enabled']) if (cols.some(x => x.column_name === n && x.data_type === 'boolean')) sets.push(`${id(n)} = true`)\n    await c.query(`update ${id(auth.usersTable)} set ${sets.join(', ')} where ${id(pkU)}::text = $2`, [hash, uid])\n    return { id: uid, criado: false }\n  }\n  const dados = { [auth.emailColumn]: email, [auth.passwordColumn]: hash }\n  if (auth.nameColumn) dados[auth.nameColumn] = nome\n  await inserir(c, auth.usersTable, pkU, dados, nome)\n  uid = await usuarioPor(c, auth, email)\n  return { id: uid, criado: true }\n}\n\n/** Coloca o usuário no grupo: linha na tabela de vínculo, ou a coluna do grupo na própria tabela de usuários (só se estiver vazia). */\nexport async function colocarNoGrupo(c, auth, userId, groupId) {\n  const link = auth.access?.link\n  if (link?.kind === 'table') {\n    const ja = (await c.query(`select 1 from ${id(link.table)} where ${id(link.userColumn)}::text = $1 and ${id(link.roleColumn)}::text = $2`, [userId, groupId])).rowCount > 0\n    if (!ja) await c.query(`insert into ${id(link.table)} (${id(link.userColumn)}, ${id(link.roleColumn)}) values ($1, $2)`, [userId, groupId])\n  } else if (link?.kind === 'column') {\n    await c.query(`update ${id(auth.usersTable)} set ${id(link.column)} = $1 where ${id(auth.usersPk || 'id')}::text = $2`, [groupId, userId])\n  }\n}\n\n/** Grupo de administração do projeto (o primeiro cujo nome tem \"admin\"), ou null. */\nexport async function grupoAdmin(c, auth) {\n  const ac = auth.access\n  if (!ac) return null\n  const grupos = (await c.query(`select ${id(ac.groupsPk)}::text as id, ${id(ac.groupsNameColumn)}::text as nome from ${id(ac.groupsTable)}`).catch(() => ({ rows: [] }))).rows\n  return grupos.find(g => /admin/i.test(g.nome)) ?? null\n}\n\n/** Cria um grupo temporário (nome E2E-Perm...). Devolve o id dele. */\nexport async function criarGrupo(c, auth, nome) {\n  const ac = auth.access\n  return inserir(c, ac.groupsTable, ac.groupsPk, { [ac.groupsNameColumn]: nome }, nome)\n}\n\n/** Define o nível de acesso (none, read, write) do grupo numa tela. */\nexport async function definirNivel(c, auth, groupId, viewSlug, nivel) {\n  const ac = auth.access\n  await c.query(`delete from ${id(ac.permsTable)} where ${id(ac.permsRoleColumn)}::text = $1 and ${id(ac.permsViewColumn)} = $2`, [groupId, viewSlug])\n  await c.query(`insert into ${id(ac.permsTable)} (${id(ac.permsRoleColumn)}, ${id(ac.permsViewColumn)}, ${id(ac.permsLevelColumn)}) values ($1, $2, $3)`, [groupId, viewSlug, nivel])\n}\n\nexport async function apagarUsuario(c, auth, userId) {\n  const link = auth.access?.link\n  if (link?.kind === 'table') await c.query(`delete from ${id(link.table)} where ${id(link.userColumn)}::text = $1`, [userId])\n  await c.query(`delete from ${id(auth.usersTable)} where ${id(auth.usersPk || 'id')}::text = $1`, [userId])\n}\n\nexport async function apagarGrupo(c, auth, groupId) {\n  const ac = auth.access\n  await c.query(`delete from ${id(ac.permsTable)} where ${id(ac.permsRoleColumn)}::text = $1`, [groupId])\n  if (ac.link?.kind === 'table') await c.query(`delete from ${id(ac.link.table)} where ${id(ac.link.roleColumn)}::text = $1`, [groupId])\n  await c.query(`delete from ${id(ac.groupsTable)} where ${id(ac.groupsPk)}::text = $1`, [groupId])\n}\n\n/** Valor do usuário que uma regra por linha compara (e-mail, nome ou uma coluna da tabela de usuários). null = a regra não tem o dado dele. */\nexport async function valorDoUsuario(c, auth, userId, source, attr) {\n  if (source === 'user.email') return (await c.query(`select ${id(auth.emailColumn)}::text as v from ${id(auth.usersTable)} where ${id(auth.usersPk || 'id')}::text = $1`, [userId])).rows[0]?.v ?? null\n  if (source === 'user.name') return auth.nameColumn ? ((await c.query(`select ${id(auth.nameColumn)}::text as v from ${id(auth.usersTable)} where ${id(auth.usersPk || 'id')}::text = $1`, [userId])).rows[0]?.v ?? null) : null\n  if (source === 'user.attr' && attr) return (await c.query(`select ${id(attr)}::text as v from ${id(auth.usersTable)} where ${id(auth.usersPk || 'id')}::text = $1`, [userId])).rows[0]?.v ?? null\n  return null\n}\n\n/** Remove o que os testes de segurança criaram e ficou para trás: usuários e2e_seg_*, grupos E2E-Perm* (com permissões e vínculos). */\nexport async function limparSeguranca(c, auth) {\n  if (!auth?.usersTable) return\n  const usuarios = (await c.query(`select ${id(auth.usersPk || 'id')}::text as id from ${id(auth.usersTable)} where ${id(auth.emailColumn)} like $1`, [EMAIL_SEG]).catch(() => ({ rows: [] }))).rows\n  for (const u of usuarios) await apagarUsuario(c, auth, u.id).catch(() => {})\n  const ac = auth.access\n  if (ac) {\n    const grupos = (await c.query(`select ${id(ac.groupsPk)}::text as id from ${id(ac.groupsTable)} where ${id(ac.groupsNameColumn)}::text like $1`, [GRUPO_SEG]).catch(() => ({ rows: [] }))).rows\n    for (const g of grupos) await apagarGrupo(c, auth, g.id).catch(() => {})\n  }\n}\n",
 "e2e/dynamic/lib/seguranca.ts": "import crypto from 'node:crypto'\nimport pg from 'pg'\nimport { CONFIG } from './config'\nimport * as acesso from './acesso.mjs'\nimport type { ManifestAuth } from '../../../src/lib/testing/manifestTypes'\n\n/** Ligação dos testes de segurança com o banco de teste: usuários, grupos e níveis de acesso temporários (tudo em lib/acesso.mjs). */\n\nexport async function comCliente<T>(fn: (c: pg.Client) => Promise<T>): Promise<T> {\n  const c = new pg.Client({ connectionString: CONFIG.dbUrl })\n  await c.connect()\n  try { return await fn(c) } finally { await c.end() }\n}\n\nexport interface UsuarioTemporario { id: string; email: string; senha: string; grupoId?: string }\n\n/** Sufixo único desta rodada (para os nomes dos usuários e grupos temporários). */\nexport const unico = () => crypto.randomBytes(4).toString('hex')\n\n/**\n * Cria um usuário temporário (e2e_seg_...) e, se pedido, um grupo temporário (E2E-Perm...) com o nível de acesso dado numa tela.\n * Devolve o que o teste precisa para entrar e para limpar depois.\n */\nexport async function criarUsuarioTemporario(auth: ManifestAuth, opts: { nivel?: { viewSlug: string; nivel: 'none' | 'read' | 'write' }; grupoSemRestricao?: boolean } = {}): Promise<UsuarioTemporario> {\n  const sufixo = unico()\n  const email = `e2e_seg_${sufixo}@metabuilder.local`\n  const senha = crypto.randomBytes(12).toString('base64url')\n  return comCliente(async c => {\n    let grupoId: string | undefined\n    // com a gestão de acesso ligada, quem não está em nenhum grupo não acessa tela nenhuma: o usuário temporário precisa de um grupo (sem linhas de permissão = telas liberadas)\n    if ((opts.nivel || opts.grupoSemRestricao) && auth.access) {\n      grupoId = await acesso.criarGrupo(c, auth, `E2E-Perm-${sufixo}`)\n      if (opts.nivel) await acesso.definirNivel(c, auth, grupoId, opts.nivel.viewSlug, opts.nivel.nivel)\n    }\n    const u = await acesso.upsertUsuario(c, auth, { email, nome: `E2E Seg ${sufixo}`, senha })\n    if (grupoId) await acesso.colocarNoGrupo(c, auth, u.id, grupoId)\n    return { id: u.id, email, senha, grupoId }\n  })\n}\n\n/** Apaga o usuário e o grupo temporários (e o que pendura neles). */\nexport async function removerUsuarioTemporario(auth: ManifestAuth, u: UsuarioTemporario) {\n  await comCliente(async c => {\n    await acesso.apagarUsuario(c, auth, u.id).catch(() => {})\n    if (u.grupoId) await acesso.apagarGrupo(c, auth, u.grupoId).catch(() => {})\n  })\n}\n\n/** Valor do usuário que a regra por linha compara. */\nexport async function valorDaRegra(auth: ManifestAuth, userId: string, source: string, attr?: string): Promise<string | null> {\n  return comCliente(c => acesso.valorDoUsuario(c, auth, userId, source, attr))\n}\n\nexport async function limparSegurancaDoBanco(auth: ManifestAuth | undefined) {\n  if (!auth || auth.type !== 'database') return\n  await comCliente(c => acesso.limparSeguranca(c, auth))\n}\n",
 "e2e/dynamic/lib/login.ts": "import { expect, type Page } from '@playwright/test'\nimport { CONFIG } from './config'\n\n/** Entra no app exportado com o usuário de teste. */\nexport async function entrar(page: Page) {\n  if (CONFIG.noAuth) return // app sem login\n  await entrarComo(page, CONFIG.user, CONFIG.password)\n}\n\n/** Entra com um usuário qualquer (os testes de segurança entram com usuários temporários). */\nexport async function entrarComo(page: Page, email: string, senha: string) {\n  await page.goto('/login')\n  await page.locator('input[name=\"email\"]').fill(email)\n  await page.locator('input[name=\"password\"]').fill(senha)\n  await page.locator('button[type=\"submit\"]').click()\n  await page.waitForURL(url => !url.pathname.startsWith('/login'), { timeout: 20_000 })\n  await expect(page.getByText('Sair do Sistema').first()).toBeVisible()\n}\n",
 "e2e/dynamic/tests/manifest.spec.ts": "import { test as base, expect, type BrowserContext, type Locator, type Page, type TestInfo } from '@playwright/test'\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { entrar, entrarComo } from '../lib/login'\nimport { criarUsuarioTemporario, removerUsuarioTemporario, valorDaRegra } from '../lib/seguranca'\nimport { consultar } from '../lib/db'\nimport { CONFIG } from '../lib/config'\nimport type { ManifestField, ManifestView, TestManifest } from '../../../src/lib/testing/manifestTypes'\nimport { aplicarMascara, camposDeTipo, camposEditaveis, campoDeFiltro, campoMarcador, describeName, ehData, mascaraDePadrao, planView, PREFIXO_E2E, regraDeLinha, type TestType } from '../../../src/lib/testing/plan'\n\n/**\n * Testes DINÂMICOS: não há um teste escrito por caso de uso. Este arquivo lê o manifesto (o que o dev configurou no Studio) e gera os testes de cada\n * caso de uso a partir do PLANO (src/lib/testing/plan.ts), o mesmo que o painel da IDE mostra antes de rodar. Caso de uso novo ou alterado no Studio\n * → manifesto novo → testes novos, sem escrever nada.\n *\n * Regras: todo caso de uso, de qualquer tipo, ganha \"a tela abre sem erro\". Pesquisa + Cadastro ganha também lista, formulário (campos, obrigatórios,\n * somente leitura, máscaras), grid (total, ordenação, filtro) e exportação (CSV, JSON, Excel). Outros tipos ganham o seu gabarito aos poucos.\n *\n * Segurança: nenhuma regra daqui grava no banco. A única que poderia (salvar o formulário vazio) só passa se o app RECUSAR; se algum registro for\n * criado por engano o teste apaga o que foi criado e falha. O guard (banco local da lista permitida, contagens e ligações conferidas no fim) vale como nos demais.\n *\n * Variáveis: E2E_MANIFEST (caminho do manifesto) e E2E_VIEWS (slugs dos casos de uso a testar, separados por vírgula; vazio = todos).\n */\n/**\n * \"Navegador interno\" da IDE: com E2E_STREAM=1 o navegador roda escondido e cada quadro da tela (screencast do Chrome) é gravado em E2E_LIVE_DIR/frame.jpg;\n * o painel da IDE lê esse arquivo e mostra a execução dentro dele. Grava num arquivo temporário e renomeia, para o painel nunca ler um quadro pela metade.\n */\nasync function transmitirTela(ctx: BrowserContext, pagina: Page): Promise<() => Promise<void>> {\n  if (process.env.E2E_STREAM !== '1') return async () => {}\n  const dir = process.env.E2E_LIVE_DIR || path.join(import.meta.dirname, '..', 'live')\n  fs.mkdirSync(dir, { recursive: true })\n  const quadro = path.join(dir, 'frame.jpg')\n  const tmp = path.join(dir, 'frame.tmp')\n  const cdp = await ctx.newCDPSession(pagina)\n  cdp.on('Page.screencastFrame', (f: { data: string; sessionId: number }) => {\n    try { fs.writeFileSync(tmp, Buffer.from(f.data, 'base64')); fs.renameSync(tmp, quadro) } catch { /* o painel leu no mesmo instante: o próximo quadro cobre */ }\n    cdp.send('Page.screencastFrameAck', { sessionId: f.sessionId }).catch(() => {})\n  })\n  await cdp.send('Page.startScreencast', { format: 'jpeg', quality: 60, maxWidth: 1280, maxHeight: 800 })\n  return async () => { await cdp.send('Page.stopScreencast').catch(() => {}) }\n}\n\n/**\n * Evidências das falhas (E2E_ARTIFACTS_DIR): captura da tela no momento da falha e vídeo do teste que falhou. O caminho dos arquivos vai para o\n * relator (anexos \"mb-shot\" e \"mb-video\") e dali para o painel e o histórico. O vídeo só existe quando cada teste tem a sua página (modo sem janela\n * do sistema); com a janela do sistema fica a captura de tela.\n */\nconst ARTEFATOS = process.env.E2E_ARTIFACTS_DIR || ''\nconst COM_JANELA = process.env.E2E_HEADED === '1'\n/** O vídeo precisa do ffmpeg do Playwright (npx playwright install ffmpeg). Sem ele, a falha fica só com a captura de tela. */\nconst TEM_FFMPEG = (() => {\n  try {\n    const raiz = process.env.PLAYWRIGHT_BROWSERS_PATH && process.env.PLAYWRIGHT_BROWSERS_PATH !== '0' ? process.env.PLAYWRIGHT_BROWSERS_PATH : path.join(process.env.LOCALAPPDATA || path.join(process.env.HOME || '', '.cache'), 'ms-playwright')\n    return fs.readdirSync(raiz).some(d => d.startsWith('ffmpeg-') && fs.readdirSync(path.join(raiz, d)).some(f => f.startsWith('ffmpeg')))\n  } catch { return false }\n})()\nconst nomeSeguro = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60)\nconst anexar = (info: TestInfo, nome: string, arquivo: string) => info.attach(nome, { body: Buffer.from(arquivo), contentType: 'text/plain' })\nlet sequencia = 0\nlet compartilhada: Page | undefined\n\n/**\n * Com a janela do sistema: uma só janela para a rodada inteira (não abre e fecha a cada teste). Sem ela: uma página nova por teste (é o que permite\n * gravar o vídeo de cada um). Nos dois casos a sessão começa limpa (cookies apagados = logout) e o login é refeito, então cada teste começa do zero.\n */\nconst test = base.extend<object, { contexto: BrowserContext }>({\n  contexto: [async ({ browser }, use) => {\n    const ctx = await browser.newContext({\n      baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR',\n      ...(COM_JANELA ? { viewport: null } : { viewport: { width: 1280, height: 800 } }),\n      ...(!COM_JANELA && ARTEFATOS && TEM_FFMPEG ? { recordVideo: { dir: path.join(ARTEFATOS, '_video'), size: { width: 1280, height: 800 } } } : {}),\n    })\n    await use(ctx)\n    await ctx.close()\n  }, { scope: 'worker' }],\n  page: async ({ contexto }, use, testInfo) => {\n    await contexto.clearCookies()\n    let pagina: Page\n    if (COM_JANELA) {\n      if (!compartilhada || compartilhada.isClosed()) compartilhada = await contexto.newPage()\n      pagina = compartilhada\n      await pagina.goto('about:blank')\n    } else {\n      pagina = await contexto.newPage()\n    }\n    const parar = await transmitirTela(contexto, pagina)\n    await use(pagina)\n    await parar()\n    const falhou = testInfo.status !== testInfo.expectedStatus\n    const base = `${String(++sequencia).padStart(3, '0')}-${nomeSeguro(testInfo.title)}`\n    if (ARTEFATOS && falhou) {\n      fs.mkdirSync(ARTEFATOS, { recursive: true })\n      try { const png = path.join(ARTEFATOS, base + '.png'); await pagina.screenshot({ path: png }); await anexar(testInfo, 'mb-shot', png) } catch { /* página já fechada */ }\n    }\n    if (!COM_JANELA) {\n      const video = pagina.video()\n      await pagina.close().catch(() => {})\n      if (video) {\n        try {\n          if (ARTEFATOS && falhou) { const webm = path.join(ARTEFATOS, base + '.webm'); await video.saveAs(webm); await anexar(testInfo, 'mb-video', webm) }\n          await video.delete()\n        } catch { /* sem vídeo desta vez */ }\n      }\n    }\n  },\n})\n\nconst MANIFEST_PATH = process.env.E2E_MANIFEST || path.join(import.meta.dirname, '..', 'manifests', 'vendas-pg.sample.json')\nconst manifest: TestManifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'))\n/** Tipos de teste desta rodada (E2E_TYPES): funcional só lê; integracao grava no banco de teste; seguranca cria usuários e grupos temporários. */\nconst TIPOS = (process.env.E2E_TYPES || 'funcional').split(',').map(x => x.trim()).filter((x): x is TestType => x === 'funcional' || x === 'integracao' || x === 'seguranca')\nconst escolhidos = (process.env.E2E_VIEWS || '').split(',').map(s => s.trim()).filter(Boolean)\n\nconst escapar = (s: string) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\nconst norm = (s: string) => s.replace(/\\s+/g, ' ').trim().toLowerCase()\n\nasync function abrir(page: Page, rota: string) {\n  await page.goto(rota)\n  await page.waitForLoadState('networkidle').catch(() => {})\n}\n\n/**\n * A lista passa por uma tela de \"Conectando ao banco...\" a cada pesquisa, ordenação ou página: só depois dela aparece o \"TOTAL: n\". Ler as linhas antes\n * disso devolve uma grid vazia. Espera o total (ou, sem ele, qualquer linha).\n */\nasync function aguardarLista(page: Page) {\n  await page.waitForLoadState('networkidle', { timeout: 10_000 }).catch(() => {})\n  await page.getByText(/Conectando ao banco/i).first().waitFor({ state: 'hidden', timeout: 15_000 }).catch(() => {})\n  await page.getByText(/TOTAL:\\s*\\d+/i).first().waitFor({ timeout: 15_000 }).catch(() => {})\n}\n\n/** Telas que não são lista (kanban, mapa, BI...): não têm \"TOTAL: n\"; espera a rede assentar e as mensagens de carregamento sumirem. */\nasync function aguardarTela(page: Page) {\n  await page.waitForLoadState('networkidle', { timeout: 10_000 }).catch(() => {})\n  await page.getByText(/Conectando ao banco|Carregando/i).first().waitFor({ state: 'hidden', timeout: 15_000 }).catch(() => {})\n}\n\n/**\n * Clica em algo que NAVEGA a lista (ordenar, pesquisar, limpar) e espera a navegação terminar: a URL muda e os dados novos chegam. Sem isso o teste lê a\n * grid da página antiga (o \"TOTAL\" dela ainda está na tela) ou no meio da troca.\n */\nasync function clicarENavegar(page: Page, alvo: Locator) {\n  const antes = page.url()\n  await alvo.click()\n  await page.waitForURL(u => u.href !== antes, { timeout: 8_000 }).catch(() => {})\n  await aguardarLista(page)\n}\n\n/** \"TOTAL: 16\" que a lista mostra. null = não achou. */\nasync function totalMostrado(page: Page): Promise<number | null> {\n  const el = page.getByText(/TOTAL:\\s*\\d+/i).first()\n  if (!(await el.count())) return null\n  const m = /TOTAL:\\s*(\\d+)/i.exec(await el.innerText())\n  return m ? Number(m[1]) : null\n}\n\n/** O total da lista; uma lista sem nenhuma linha não mostra \"TOTAL: n\" e conta como 0. */\nasync function totalOuZero(page: Page): Promise<number | null> {\n  const total = await totalMostrado(page)\n  if (total !== null) return total\n  return (await linhasDoGrid(page)).length === 0 ? 0 : null\n}\n\n/** Posição da coluna do grid pelo rótulo (o cabeçalho e as células têm a mesma ordem). */\nasync function indiceColuna(page: Page, rotulo: string): Promise<number> {\n  const ths = await page.locator('thead th').allInnerTexts()\n  return ths.findIndex(t => norm(t).startsWith(norm(rotulo)))\n}\n\n/** Textos das células de cada linha de dados do grid (a linha \"sem registros\" tem uma célula só e fica de fora). */\nasync function linhasDoGrid(page: Page): Promise<string[][]> {\n  return page.locator('tbody tr').evaluateAll(trs =>\n    trs.map(tr => Array.from(tr.querySelectorAll('td')).map(td => (td as HTMLElement).innerText.trim())).filter(c => c.length > 1))\n}\n\nasync function baixar(page: Page, formato: RegExp) {\n  await page.getByRole('button', { name: /^Exportar/ }).first().click()\n  const [download] = await Promise.all([page.waitForEvent('download'), page.getByRole('button', { name: formato }).click()])\n  return { name: download.suggestedFilename(), buf: fs.readFileSync((await download.path())!) }\n}\n\n/** Cabeçalho e número de registros de um CSV (aspas protegem quebras de linha dentro do texto). */\nfunction lerCsv(texto: string): { cabecalho: string; registros: number } {\n  const t = texto.replace(/^﻿/, '')\n  const linhas: string[] = []\n  let emAspas = false\n  let inicio = 0\n  for (let i = 0; i < t.length; i++) {\n    const ch = t[i]\n    if (ch === '\"') emAspas = !emAspas\n    else if (ch === '\\n' && !emAspas) { linhas.push(t.slice(inicio, i).replace(/\\r$/, '')); inicio = i + 1 }\n  }\n  if (inicio < t.length) linhas.push(t.slice(inicio))\n  const dados = linhas.filter(l => l.length > 0)\n  return { cabecalho: dados[0] ?? '', registros: Math.max(0, dados.length - 1) }\n}\n\n// ---------------------------------------------------------------------------------------------------------------------\n// Integração: cadastro, reabrir, edição e exclusão com dados gerados (gravam no banco de teste; só com o tipo \"integracao\")\n// ---------------------------------------------------------------------------------------------------------------------\n\n/** Identificador desta rodada: todo texto gerado começa com \"E2E-\" (a limpeza de sobras só apaga linhas assim). */\nconst RODADA = PREFIXO_E2E + new Date().toISOString().replace(/[-:T]/g, '').slice(2, 12) // E2E-2610191430\n\ninterface Preenchido { tipo: 'texto' | 'texto-mascara' | 'numero-mascara' | 'numero' | 'data' | 'data-hora' | 'hora' | 'bool' | 'opcao'; esperado: string; numero?: number }\ninterface EstadoCrud { marcador: string; id?: string; preenchidos: Record<string, Preenchido>; criouEm?: number }\n/**\n * O estado entre as etapas (cadastro → reabrir → edição → exclusão) fica em arquivo, não na memória: quando um teste falha o Playwright reinicia o\n * processo de teste e a memória se perde, e as etapas seguintes ficariam sem saber qual registro foi criado.\n */\nconst arquivoEstado = (slug: string) => path.join(import.meta.dirname, '..', '..', 'test-results-dynamic', `crud-${slug}.json`)\nconst lerEstado = (slug: string): EstadoCrud | undefined => { try { return JSON.parse(fs.readFileSync(arquivoEstado(slug), 'utf8')) as EstadoCrud } catch { return undefined } }\nfunction gravarEstado(slug: string, e: EstadoCrud | undefined) {\n  fs.mkdirSync(path.dirname(arquivoEstado(slug)), { recursive: true })\n  if (e) fs.writeFileSync(arquivoEstado(slug), JSON.stringify(e))\n  else fs.rmSync(arquivoEstado(slug), { force: true })\n}\n\n/** Tamanho máximo das colunas de texto da tabela (para o valor gerado caber). */\nasync function limitesDaTabela(tabela: string): Promise<Record<string, number>> {\n  const r = await consultar(`select column_name, character_maximum_length as n from information_schema.columns where table_name = $1 and table_schema = current_schema() and character_maximum_length is not null`, [tabela])\n  return Object.fromEntries(r.map(x => [String(x.column_name), Number(x.n)]))\n}\nconst caber = (txt: string, limite?: number) => (limite && txt.length > limite ? txt.slice(0, limite) : txt)\n\n/** Preenche UM campo do formulário com um valor gerado, pelo tipo do componente na tela. Devolve o que gravou, ou null se o campo não dá para preencher. */\nasync function preencherCampo(page: Page, f: ManifestField, n: number, limites: Record<string, number>, marcador?: string): Promise<Preenchido | null> {\n  const campo = page.locator(`[name=\"${f.column}\"]`).first()\n  if (!(await campo.count())) return null\n  if ((await campo.isDisabled()) || (await campo.getAttribute('readonly')) !== null) return null\n  const tag = await campo.evaluate(e => e.tagName.toLowerCase())\n  const tipo = (await campo.getAttribute('type')) ?? ''\n  if (tag === 'select') {\n    const opcoes = await campo.locator('option').evaluateAll(os => os.map(o => (o as HTMLOptionElement).value).filter(v => v !== ''))\n    if (opcoes.length === 0) return null\n    await campo.selectOption(opcoes[0])\n    return { tipo: 'opcao', esperado: opcoes[0] }\n  }\n  if (tipo === 'checkbox') { await campo.check(); return { tipo: 'bool', esperado: 'true' } }\n  if (tipo === 'date') { await campo.fill('2026-10-25'); return { tipo: 'data', esperado: '2026-10-25' } }\n  if (tipo === 'datetime-local') { await campo.fill('2026-10-25T12:00'); return { tipo: 'data-hora', esperado: '2026-10-25' } }\n  if (tipo === 'time') { await campo.fill('12:00'); return { tipo: 'hora', esperado: '12:00' } }\n  if (tipo === 'number') { await campo.fill(String(7 + n)); return { tipo: 'numero', esperado: String(7 + n), numero: 7 + n } }\n  if (tag !== 'input' && tag !== 'textarea') return null\n  // máscara de padrão (CPF, CNPJ, telefone...): digita os dígitos e a tela formata\n  if (mascaraDePadrao(f.mask)) {\n    const digitos = '1234567890123456789'.slice(0, (f.mask as string).split('0').length - 1)\n    await campo.click(); await campo.pressSequentially(digitos)\n    return { tipo: 'texto-mascara', esperado: digitos }\n  }\n  // máscara numérica (0.000,00 / 0.000): os dígitos entram como centavos\n  if (f.mask && /^0[0.,]*0$/.test(f.mask) && /int|numeric|decimal|float|double|number/i.test(f.dataType)) {\n    const casas = f.mask.includes(',') ? f.mask.split(',')[1].length : 0\n    const digitos = String(1250 + n * 100)\n    await campo.click(); await campo.pressSequentially(casas ? digitos : String(7 + n))\n    return { tipo: 'numero-mascara', esperado: casas ? digitos : String(7 + n), numero: casas ? Number(digitos) / 10 ** casas : 7 + n }\n  }\n  if (/int|numeric|decimal|float|double|number/i.test(f.dataType)) { await campo.fill(String(7 + n)); return { tipo: 'numero', esperado: String(7 + n), numero: 7 + n } }\n  const texto = marcador ?? (/e-?mail/i.test(f.column) ? `e2e${n}@e2e.com.br` : `E2E texto ${n}`)\n  const valor = caber(texto, limites[f.column])\n  await campo.fill(valor)\n  return { tipo: 'texto', esperado: valor }\n}\n\n/** O que está no banco confere com o que o teste preencheu? Devolve a descrição da diferença, ou null se confere. */\nfunction conferirNoBanco(f: ManifestField, esp: Preenchido, noBanco: string | null): string | null {\n  const v = noBanco ?? ''\n  const ok = esp.tipo === 'bool' ? /^(t|true|1)$/i.test(v)\n    : esp.tipo === 'data' || esp.tipo === 'data-hora' ? v.startsWith(esp.esperado.slice(0, 10))\n    : esp.tipo === 'hora' ? v.startsWith(esp.esperado)\n    : esp.tipo === 'numero' || esp.tipo === 'numero-mascara' ? Number(v) === esp.numero\n    : esp.tipo === 'texto-mascara' ? v.replace(/\\D/g, '') === esp.esperado\n    : v === esp.esperado\n  return ok ? null : `\"${f.label}\": esperado ${esp.esperado}, no banco \"${v}\"`\n}\n\n/** A tela, ao reabrir o registro, mostra o que foi gravado? */\nasync function conferirNaTela(page: Page, f: ManifestField, esp: Preenchido): Promise<string | null> {\n  const campo = page.locator(`[name=\"${f.column}\"]`).first()\n  if (esp.tipo === 'bool') return (await campo.isChecked()) ? null : `\"${f.label}\": a caixa deveria estar marcada`\n  const v = await campo.inputValue()\n  const ok = esp.tipo === 'data' ? v === esp.esperado\n    : esp.tipo === 'data-hora' ? v.startsWith(esp.esperado.slice(0, 10))\n    : esp.tipo === 'numero' ? Number(v) === esp.numero\n    : esp.tipo === 'numero-mascara' ? Number(v.replace(/\\./g, '').replace(',', '.')) === esp.numero\n    : esp.tipo === 'texto-mascara' ? v.replace(/\\D/g, '') === esp.esperado\n    : v === esp.esperado\n  return ok ? null : `\"${f.label}\": esperado ${esp.esperado}, a tela mostra \"${v}\"`\n}\n\n/** O registro criado pelo cadastro ainda está no banco? Se não, as etapas seguintes falham logo, com a causa, em vez de esperar o tempo limite da tela. */\nasync function registroExiste(view: ManifestView, id: string): Promise<boolean> {\n  return Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [id]))[0].n) > 0\n}\n\n/** Acha a linha com o texto, passando pelas páginas da lista (a linha criada pode não estar na primeira). */\nasync function acharLinha(page: Page, texto: string): Promise<Locator | null> {\n  for (let pagina = 1; pagina <= 20; pagina++) {\n    const linha = page.locator('tbody tr').filter({ hasText: texto }).first()\n    if (await linha.count()) return linha\n    const proxima = page.getByRole('link', { name: String(pagina + 1), exact: true })\n    if (!(await proxima.count())) return null\n    await clicarENavegar(page, proxima)\n  }\n  return null\n}\n\n/** Confirma a exclusão: caixa de diálogo do navegador ou janela de confirmação do app. */\nasync function confirmarExclusao(page: Page) {\n  page.once('dialog', d => d.accept())\n  await page.getByRole('button', { name: /excluir|confirmar/i }).last().click({ timeout: 4000 }).catch(() => {})\n}\n\nfor (const view of manifest.views.filter(v => escolhidos.length === 0 || escolhidos.includes(v.slug))) {\n  test.describe(describeName(view), () => {\n    test.beforeEach(async ({ page }) => { await entrar(page) })\n\n    for (const t of planView(view, { types: TIPOS, auth: manifest.auth })) {\n      if (t.kind === 'abre') {\n        test(t.title, async ({ page }) => {\n          const erros: string[] = []\n          page.on('pageerror', e => erros.push(e.message.slice(0, 200)))\n          const resp = await page.goto(view.path)\n          expect(resp?.status() ?? 0, `HTTP de ${view.path}`).toBeLessThan(400)\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.locator('main').first()).toBeVisible()\n          const texto = await page.locator('body').innerText()\n          expect(texto).not.toMatch(/Application error|Internal Server Error|Unhandled Runtime Error|Erro ao carregar/i)\n          expect(texto.toLowerCase(), `o título \"${view.title}\" aparece na tela`).toContain(view.title.toLowerCase())\n          expect(erros, 'erros de JavaScript na página').toEqual([])\n        })\n      }\n\n      if (t.kind === 'lista') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          for (const f of view.filter) {\n            await expect.soft(page.locator(`[name=\"${f.column}_filter\"]`).first(), `filtro \"${f.label}\" (${f.column}_filter)`).toBeVisible()\n          }\n          for (const f of view.grid) {\n            await expect.soft(page.locator('thead th').filter({ hasText: new RegExp(escapar(f.label), 'i') }).first(), `coluna \"${f.label}\" no grid`).toBeVisible()\n          }\n        })\n      }\n\n      if (t.kind === 'formulario') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          for (const f of camposEditaveis(view)) {\n            const campo = page.locator(`[name=\"${f.column}\"]`).first()\n            await expect.soft(campo, `campo \"${f.label}\" (${f.column})`).toBeVisible()\n            if (!(await campo.count())) continue\n            if (f.dataType !== 'boolean') {\n              const obrigatorio = (await campo.getAttribute('required')) !== null\n              expect.soft(obrigatorio, `\"${f.label}\": obrigatório esperado ${f.required}`).toBe(f.required)\n            }\n            if (f.readOnly) {\n              const travado = (await campo.getAttribute('readonly')) !== null || (await campo.isDisabled())\n              expect.soft(travado, `\"${f.label}\": deveria ser somente leitura`).toBe(true)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'mascara') {\n        const f = view.form.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          const digitos = '1234567890123456789'.slice(0, (f.mask as string).split('0').length - 1)\n          const campo = page.locator(`[name=\"${f.column}\"]`).first()\n          await campo.click()\n          await campo.pressSequentially(digitos)\n          await expect(campo).toHaveValue(aplicarMascara(digitos, f.mask as string))\n        })\n      }\n\n      if (t.kind === 'obrigatorios') {\n        test(t.title, async ({ page }) => {\n          const ids = async () => new Set((await consultar(`select ${view.primaryKey}::text as id from ${view.table}`)).map(r => String(r.id)))\n          const antes = await ids()\n          await abrir(page, `${view.path}/new`)\n          await page.getByRole('button', { name: 'Criar Registro' }).first().click()\n          await page.waitForTimeout(1500)\n          const novos = [...(await ids())].filter(id => !antes.has(id))\n          if (novos.length > 0) {\n            // o app aceitou salvar vazio: apaga só o que esta tela criou e falha\n            for (const id of novos) await consultar(`delete from ${view.table} where ${view.primaryKey}::text = $1`, [id])\n          }\n          expect(novos, `o app criou ${novos.length} registro(s) com os campos obrigatórios vazios`).toEqual([])\n        })\n      }\n\n      if (t.kind === 'grid_total') {\n        test(t.title, async ({ page }) => {\n          const noBanco = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const naTela = await totalMostrado(page)\n          expect(naTela, 'a lista mostra \"TOTAL: n\"').not.toBeNull()\n          expect(naTela, `total da tela × linhas da tabela ${view.table}`).toBe(noBanco)\n        })\n      }\n\n      if (t.kind === 'grid_ordenacao') {\n        const campo = view.grid.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const idx = await indiceColuna(page, campo.label)\n          expect(idx, `coluna \"${campo.label}\" no grid`).toBeGreaterThanOrEqual(0)\n          const clicar = () => clicarENavegar(page, page.locator('thead th').nth(idx).locator('a, button').first())\n          await clicar()\n          const asc = (await linhasDoGrid(page)).map(c => c[idx])\n          await clicar()\n          const desc = (await linhasDoGrid(page)).map(c => c[idx])\n          const total = await totalMostrado(page)\n          if (total) expect(asc.length, 'linhas na ordem crescente (a lista não pode vir vazia se o total é maior que zero)').toBeGreaterThan(0)\n          test.skip(asc.length < 2 || new Set(asc).size < 2, 'poucos valores diferentes para conferir a ordem')\n          if (total !== null && total > asc.length) expect(desc[0], 'com várias páginas, o primeiro da ordem decrescente muda').not.toBe(asc[0])\n          else expect(desc, 'a ordem decrescente é o inverso da crescente').toEqual([...asc].reverse())\n        })\n      }\n\n      if (t.kind === 'grid_filtro') {\n        const campo = view.filter.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          const [linha] = await consultar(`select ${campo.column}::text as v from ${view.table} where ${campo.column} is not null and ${campo.column}::text <> '' limit 1`)\n          test.skip(!linha, 'a tabela não tem dados para filtrar')\n          const valor = String(linha.v)\n          const busca = (valor.split(/\\s+/).find(w => w.length >= 3) ?? valor).slice(0, 20)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const entrada = page.locator(`[name=\"${campo.column}_filter\"]`).first()\n          await entrada.fill(busca)\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          const linhas = await linhasDoGrid(page)\n          expect(linhas.length, `linhas depois de filtrar por \"${busca}\"`).toBeGreaterThan(0)\n          for (const c of linhas) expect.soft(c.join(' ').toLowerCase(), 'linha fora do filtro').toContain(busca.toLowerCase())\n          await clicarENavegar(page, page.getByRole('link', { name: 'Limpar' }).or(page.getByRole('button', { name: 'Limpar' })).first())\n          await expect(page.locator(`[name=\"${campo.column}_filter\"]`).first()).toHaveValue('')\n        })\n      }\n\n      if (t.kind === 'exportacao') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const total = await totalMostrado(page)\n          if (t.format === 'csv') {\n            const r = await baixar(page, /csv/i)\n            expect(r.name).toMatch(/\\.csv$/i)\n            const csv = lerCsv(r.buf.toString('utf8'))\n            for (const f of view.grid) expect.soft(csv.cabecalho, `coluna \"${f.label}\" no cabeçalho do CSV`).toContain(f.label)\n            if (total !== null) expect(csv.registros, 'linhas do CSV × total da lista').toBe(total)\n          } else if (t.format === 'json') {\n            const r = await baixar(page, /json/i)\n            expect(r.name).toMatch(/\\.json$/i)\n            const itens = JSON.parse(r.buf.toString('utf8'))\n            expect(Array.isArray(itens), 'o JSON é uma lista').toBe(true)\n            if (total !== null) expect(itens.length, 'itens do JSON × total da lista').toBe(total)\n          } else {\n            const r = await baixar(page, /excel|xlsx/i)\n            expect(r.name).toMatch(/\\.xlsx$/i)\n            expect(r.buf.subarray(0, 2).toString('latin1'), 'um .xlsx é um zip (começa com PK)').toBe('PK')\n            expect(r.buf.length).toBeGreaterThan(1000)\n          }\n        })\n      }\n\n      // ---------------------------------------------------------------------------------------------------------------------\n      // Fase 3 (só leitura)\n      // ---------------------------------------------------------------------------------------------------------------------\n\n      if (t.kind === 'grid_paginacao') {\n        test(t.title, async ({ page }) => {\n          const noBanco = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const seletor = page.locator('main select').last()\n          const rotulos = await seletor.locator('option').allInnerTexts()\n          const tamanhos = rotulos.map(r => ({ r, n: Number(/\\d+/.exec(r)?.[0]) })).filter(x => x.n > 0).sort((a, b) => a.n - b.n)\n          expect(tamanhos.length, 'o seletor de linhas por página tem opções').toBeGreaterThan(0)\n          const menor = tamanhos[0]\n          const antes = page.url()\n          await seletor.selectOption({ label: menor.r })\n          await page.waitForURL(u => u.href !== antes, { timeout: 8_000 }).catch(() => {})\n          await aguardarLista(page)\n          expect(await totalMostrado(page), 'o total não muda com o tamanho da página').toBe(noBanco)\n          expect((await linhasDoGrid(page)).length, `linhas com ${menor.n} por página`).toBe(Math.min(menor.n, noBanco))\n          if (noBanco > menor.n) {\n            await clicarENavegar(page, page.getByRole('link', { name: '2', exact: true }))\n            expect((await linhasDoGrid(page)).length, 'linhas da página 2').toBe(Math.min(menor.n, noBanco - menor.n))\n          }\n        })\n      }\n\n      if (t.kind === 'filtro_opcoes') {\n        const campo = view.filter.find(x => x.column === t.field)!\n        const gcol = view.grid.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          let escolha: { label: string; n: number } | undefined\n          for (const o of campo.options ?? []) {\n            const n = Number((await consultar(`select count(*) n from ${view.table} where ${campo.column}::text = $1`, [o.value]))[0].n)\n            if (n > 0 && n < total) { escolha = { label: o.label, n }; break }\n          }\n          test.skip(!escolha, 'nenhuma opção do filtro separa as linhas (todas ou nenhuma)')\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          await page.locator(`select[name=\"${campo.column}_filter\"]`).selectOption({ label: escolha!.label })\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          expect(await totalMostrado(page), `total com \"${escolha!.label}\"`).toBe(escolha!.n)\n          const idx = await indiceColuna(page, gcol.label)\n          expect(idx, `coluna \"${gcol.label}\"`).toBeGreaterThanOrEqual(0)\n          for (const c of await linhasDoGrid(page)) expect.soft(norm(c[idx]), 'linha de outra opção').toContain(norm(escolha!.label))\n          await clicarENavegar(page, page.getByRole('link', { name: 'Limpar' }).or(page.getByRole('button', { name: 'Limpar' })).first())\n          expect(await totalMostrado(page), 'Limpar volta ao total').toBe(total)\n        })\n      }\n\n      if (t.kind === 'visualizar') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const icone = page.locator('main a[title=\"Visualizar\"]').first()\n          test.skip(!(await icone.count()), 'sem registros para visualizar')\n          await icone.click()\n          await page.waitForURL(/mode=view/, { timeout: 8_000 })\n          await page.waitForLoadState('networkidle').catch(() => {})\n          const editavel = camposEditaveis(view).find(f => f.dataType !== 'boolean')\n          if (editavel) {\n            const campo = page.locator(`[name=\"${editavel.column}\"]`).first()\n            await expect(campo).toBeVisible()\n            const travado = (await campo.isDisabled()) || (await campo.getAttribute('readonly')) !== null\n            expect(travado, `\"${editavel.label}\" deveria estar travado no modo Visualizar`).toBe(true)\n          }\n          await expect(page.getByRole('button', { name: /Salvar Alterações|Criar Registro/ })).toHaveCount(0)\n        })\n      }\n\n      if (t.kind === 'exportacao_filtrada') {\n        const campo = view.filter.find(x => x.column === (campoDeFiltro(view) as ManifestField).column)!\n        test(t.title, async ({ page }) => {\n          const [linha] = await consultar(`select ${campo.column}::text as v from ${view.table} where ${campo.column} is not null and ${campo.column}::text <> '' limit 1`)\n          test.skip(!linha, 'a tabela não tem dados para filtrar')\n          const busca = (String(linha.v).split(/\\s+/).find(w => w.length >= 3) ?? String(linha.v)).slice(0, 20)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const todos = await totalMostrado(page)\n          await page.locator(`[name=\"${campo.column}_filter\"]`).first().fill(busca)\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          const filtrados = await totalMostrado(page)\n          expect(filtrados, 'o filtro achou registros').toBeGreaterThan(0)\n          const r = await baixar(page, /csv/i)\n          const csv = lerCsv(r.buf.toString('utf8'))\n          expect(csv.registros, `linhas do CSV × total filtrado (o banco inteiro tem ${todos})`).toBe(filtrados)\n        })\n      }\n\n      if (t.kind === 'exportacao_marcadas') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const marcas = page.locator('tbody input[type=\"checkbox\"]')\n          test.skip((await marcas.count()) < 2, 'menos de 2 linhas para marcar')\n          await marcas.nth(0).check()\n          await marcas.nth(1).check()\n          await expect(page.getByRole('button', { name: /^Exportar.*\\(2\\)/ })).toBeVisible()\n          const r = await baixar(page, /json/i)\n          expect((JSON.parse(r.buf.toString('utf8')) as unknown[]).length, 'itens exportados × linhas marcadas').toBe(2)\n          await page.locator('thead input[type=\"checkbox\"]').check()\n          const total = await marcas.count()\n          await expect(page.getByRole('button', { name: new RegExp(`^Exportar.*\\\\(${total}\\\\)`) })).toBeVisible()\n          await page.locator('thead input[type=\"checkbox\"]').uncheck()\n          await expect(page.getByRole('button', { name: /^Exportar/ }).first()).not.toContainText('(')\n        })\n      }\n\n      if (t.kind === 'central_downloads') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const r = await baixar(page, /csv/i)\n          const base = r.name.replace(/-\\d{4}-\\d{2}-\\d{2}\\.csv$/i, '')\n          await abrir(page, '/downloads')\n          const arquivos = page.getByText(new RegExp(`^${escapar(base)}-\\\\d{8}-\\\\d{6}-[0-9a-f]{4}\\\\.csv$`))\n          await expect(arquivos.first(), `a Central de Downloads lista a exportação de ${base}`).toBeVisible()\n          const [dl] = await Promise.all([page.waitForEvent('download'), page.locator('a[title=\"Baixar\"]').first().click()])\n          const conteudo = fs.readFileSync((await dl.path())!).toString('utf8')\n          expect(lerCsv(conteudo).cabecalho.length, 'o arquivo baixado tem cabeçalho').toBeGreaterThan(0)\n        })\n      }\n\n      if (t.kind === 'botoes') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const linhas = (await linhasDoGrid(page)).length\n          for (const b of view.buttons) {\n            const nome = new RegExp(`^${escapar(b.label)}`, 'i')\n            if (b.actionType === 'export') await expect.soft(page.getByRole('button', { name: nome }).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (b.actionType === 'search') await expect.soft(page.getByRole('button', { name: nome }).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (b.actionType === 'clear') await expect.soft(page.getByRole('link', { name: nome }).or(page.getByRole('button', { name: nome })).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (linhas > 0 && ['view', 'edit', 'delete'].includes(b.actionType)) {\n              expect.soft(await page.locator(`main [title=\"${b.label}\"]`).count(), `ícone \"${b.label}\" nas linhas`).toBeGreaterThan(0)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'campos_tipos') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          for (const f of camposDeTipo(view)) {\n            const campo = page.locator(`[name=\"${f.column}\"]`).first()\n            if (!(await campo.count())) { expect.soft(0, `campo \"${f.label}\" (${f.column}) existe`).toBeGreaterThan(0); continue }\n            const tag = await campo.evaluate(e => e.tagName.toLowerCase())\n            const tipo = (await campo.getAttribute('type')) ?? ''\n            if (f.options?.length) {\n              expect.soft(tag, `\"${f.label}\" com opções é uma lista de seleção`).toBe('select')\n              if (tag === 'select') expect.soft(await campo.locator('option').count(), `opções de \"${f.label}\"`).toBeGreaterThanOrEqual(f.options.length)\n            } else if (f.dataType === 'boolean') {\n              expect.soft(tipo, `\"${f.label}\" é uma caixa de marcar`).toBe('checkbox')\n            } else if (ehData(f)) {\n              expect.soft(['date', 'datetime-local', 'time'], `\"${f.label}\" usa o seletor de data`).toContain(tipo)\n            } else if (/select/i.test(f.componentType || '')) {\n              expect.soft(tag, `\"${f.label}\" é uma lista de seleção`).toBe('select')\n            } else if (/int|numeric|decimal|float|double|number/i.test(f.dataType)) {\n              expect.soft(['number', 'text'], `\"${f.label}\" é um campo numérico`).toContain(tipo)\n            } else {\n              expect.soft(['input', 'textarea', 'select'], `\"${f.label}\" é um campo de entrada`).toContain(tag)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'abas') {\n        test(t.title, async ({ page }) => {\n          const [reg] = await consultar(`select ${view.primaryKey}::text as id from ${view.table} limit 1`)\n          test.skip(!reg, 'a tabela não tem registros para abrir')\n          await abrir(page, `${view.path}/${reg.id}`)\n          for (const d of view.details) {\n            const nome = new RegExp(`^${escapar(d.label)}$`, 'i')\n            if (d.displayMode === 'tab') {\n              const aba = page.getByRole('button', { name: nome }).first()\n              await expect.soft(aba, `aba \"${d.label}\"`).toBeVisible()\n              if (await aba.count()) {\n                await aba.click()\n                await expect.soft(page.getByText(/Application error|Erro ao carregar/i), `erro ao abrir a aba \"${d.label}\"`).toHaveCount(0)\n              }\n            } else {\n              await expect.soft(page.getByText(nome).first(), `seção \"${d.label}\"`).toBeVisible()\n            }\n          }\n        })\n      }\n\n      // --- gabaritos por tipo de tela (todos só leem) ---\n\n      if (t.kind === 'filtros_tela') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          let achados = 0\n          for (const f of view.filter) if (await page.locator(`[name=\"${f.column}_filter\"]`).count()) achados++\n          if (achados > 0) expect(achados, 'filtros com nome na tela × filtros configurados').toBe(view.filter.length)\n          else {\n            // tela sem nomes nos campos (ex.: timeline): confere pela quantidade de listas de seleção\n            const listas = view.filter.filter(f => f.options?.length || /select|autocomplete/i.test(f.componentType || '') || /uuid/i.test(f.dataType)).length\n            expect(await page.locator('main select').count(), 'listas de filtro na tela').toBeGreaterThanOrEqual(Math.min(listas, 1))\n          }\n        })\n      }\n\n      if (t.kind === 'tipo_galeria') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('main img'), 'um cartão (imagem) por registro').toHaveCount(total)\n        })\n      }\n\n      if (t.kind === 'tipo_kanban') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          const cartoes = await page.locator('main button[title=\"Detalhes\"]').count()\n          const mais = Number(/CARREGAR MAIS\\s+(\\d+)/i.exec(await page.locator('main').innerText())?.[1] ?? 0)\n          expect(cartoes + mais, `cartões na tela (${cartoes}) + a carregar (${mais}) × registros da tabela`).toBe(total)\n        })\n      }\n\n      if (t.kind === 'tipo_fluxo') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('.react-flow')).toBeVisible()\n          await expect(page.getByText(new RegExp(`${total} ETAPAS`, 'i')).first(), `\"${total} ETAPAS\" na tela`).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_timeline') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('button[title=\"Atualizar Dados\"], button:has-text(\"Atualizar Dados\")').first()).toBeVisible()\n          await page.locator('button[title=\"Atualizar Dados\"], button:has-text(\"Atualizar Dados\")').first().click()\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n        })\n      }\n\n      if (t.kind === 'tipo_gantt') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByRole('button', { name: /^Hoje$/i })).toBeVisible()\n          for (const tam of ['Pequeno', 'Normal', 'Grande']) await expect.soft(page.locator(`main button[title=\"${tam}\"]`).first(), `tamanho \"${tam}\"`).toBeVisible()\n          const linhas = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          if (linhas > 0) expect(await page.locator('main [title=\"Editar\"]').count(), 'ações de linha (Editar)').toBeGreaterThan(0)\n        })\n      }\n\n      if (t.kind === 'tipo_agenda') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByText(/de 20\\d\\d/i).first()).toBeVisible()\n          const texto = async () => (await page.locator('main').innerText()).replace(/\\s+/g, ' ')\n          const mes = await texto()\n          await page.getByRole('button', { name: 'Semana', exact: true }).click()\n          const semana = await texto()\n          await page.getByRole('button', { name: 'Dia', exact: true }).click()\n          const dia = await texto()\n          expect(new Set([mes, semana, dia]).size, 'mês, semana e dia mostram coisas diferentes').toBe(3)\n          await page.getByRole('button', { name: 'Mês', exact: true }).click()\n          await expect(page.getByText('DOM').first()).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_mapa_mental') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByText(new RegExp(`${total} REGISTROS`, 'i')).first(), `\"${total} REGISTROS\" na tela`).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_mapa') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          const lat = view.form.find(f => /^lat/i.test(f.column))?.column\n          const lng = view.form.find(f => /^(lng|lon)/i.test(f.column))?.column\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('.leaflet-container')).toBeVisible()\n          await expect(page.getByText(new RegExp(`REGISTROS \\\\(${total}\\\\)`, 'i')).first(), `\"REGISTROS (${total})\"`).toBeVisible()\n          if (lat && lng) {\n            const comGps = Number((await consultar(`select count(*) n from ${view.table} where ${lat} is not null and ${lng} is not null`))[0].n)\n            await expect(page.getByText(new RegExp(`${comGps} DE ${total} REGISTROS COM COORDENADAS`, 'i')).first()).toBeVisible()\n          }\n        })\n      }\n\n      if (t.kind === 'tipo_bi') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByRole('button', { name: 'Atualizar agora' })).toBeVisible()\n          await expect(page.getByRole('button', { name: 'Organizar Dashboard' })).toBeVisible()\n          await page.getByRole('button', { name: 'Atualizar agora' }).click()\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n          expect(await page.locator('tbody tr').count(), 'linhas na tabela de dados').toBeGreaterThan(0)\n        })\n      }\n\n      // --- integração: grava no banco de teste (só roda com o tipo \"integracao\") ---\n\n      if (t.kind === 'crud_cadastro') {\n        test(t.title, async ({ page }) => {\n          const marcadorCampo = campoMarcador(view)!\n          const editaveis = camposDeTipo(view).filter(f => !f.readOnly)\n          const limites = await limitesDaTabela(view.table)\n          const marcador = caber(`${RODADA}-${view.slug.replace(/[^a-z0-9]/gi, '').slice(0, 6)}`, limites[marcadorCampo.column])\n          test.skip(!marcador.startsWith(PREFIXO_E2E) || marcador.length < 8, 'a coluna de identificação é curta demais para o prefixo E2E-')\n          const estado: EstadoCrud = { marcador, preenchidos: {} }\n          gravarEstado(view.slug, estado)\n\n          await abrir(page, `${view.path}/new`)\n          const naoPreenchidos: string[] = []\n          let n = 0\n          for (const f of editaveis) {\n            const p = await preencherCampo(page, f, ++n, limites, f.column === marcadorCampo.column ? marcador : undefined)\n            if (p) estado.preenchidos[f.column] = p\n            else if (f.required) naoPreenchidos.push(f.label)\n          }\n          test.skip(naoPreenchidos.length > 0, `campo(s) obrigatório(s) que o motor ainda não sabe preencher: ${naoPreenchidos.join(', ')}`)\n          if (process.env.E2E_DEBUG) console.log(`[crud ${view.slug}] preenchido: ${JSON.stringify(estado.preenchidos)}`)\n\n          await page.getByRole('button', { name: 'Criar Registro' }).first().click()\n          await expect.poll(async () => (await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n, { message: 'o registro aparece no banco', timeout: 15_000 }).toBe(1)\n          const cols = Object.keys(estado.preenchidos)\n          const [linha] = await consultar(`select \"${view.primaryKey}\"::text as \"__id\", ${cols.map(c => `\"${c}\"::text as \"${c}\"`).join(', ')} from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador])\n          estado.id = String(linha.__id)\n          gravarEstado(view.slug, estado)\n          // auditoria: se a tabela tem criado_por, o app precisa tê-lo gravado (quem criou o registro)\n          const colunaAuditoria = await consultar(`select 1 from information_schema.columns where table_name = $1 and table_schema = current_schema() and column_name = 'criado_por'`, [view.table])\n          if (colunaAuditoria.length > 0) {\n            const [aud] = await consultar(`select (\"criado_por\" is not null) as ok from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [estado.id])\n            expect.soft(aud.ok, 'auditoria: criado_por gravado no registro criado').toBe(true)\n          }\n          for (const f of editaveis) {\n            const esp = estado.preenchidos[f.column]\n            if (!esp) continue\n            const dif = conferirNoBanco(f, esp, linha[f.column])\n            expect.soft(dif, 'campo gravado no banco').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'crud_reabrir') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          expect(await registroExiste(view, estado.id!), 'o registro criado pelo cadastro continua no banco').toBe(true)\n          await abrir(page, `${view.path}/${estado.id}`)\n          for (const f of camposDeTipo(view)) {\n            const esp = estado.preenchidos[f.column]\n            if (!esp) continue\n            expect.soft(await conferirNaTela(page, f, esp), 'campo mostrado ao reabrir').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'crud_edicao') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          const marcadorCampo = campoMarcador(view)!\n          const limites = await limitesDaTabela(view.table)\n          const novo = caber(`${estado.marcador} ED`, limites[marcadorCampo.column])\n          test.skip(novo === estado.marcador, 'a coluna de identificação não comporta a alteração')\n          expect(await registroExiste(view, estado.id!), 'o registro criado pelo cadastro continua no banco').toBe(true)\n          await abrir(page, `${view.path}/${estado.id}`)\n          await page.locator(`[name=\"${marcadorCampo.column}\"]`).first().fill(novo)\n          await page.getByRole('button', { name: 'Salvar Alterações' }).first().click()\n          await expect.poll(async () => String((await consultar(`select \"${marcadorCampo.column}\"::text as v from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [estado.id]))[0]?.v), { message: 'a alteração aparece no banco', timeout: 15_000 }).toBe(novo)\n          estado.marcador = novo\n          estado.preenchidos[marcadorCampo.column] = { tipo: 'texto', esperado: novo }\n          gravarEstado(view.slug, estado)\n          // só o campo alterado mudou: os demais continuam como foram gravados\n          const cols = Object.keys(estado.preenchidos)\n          const [linha] = await consultar(`select ${cols.map(c => `\"${c}\"::text as \"${c}\"`).join(', ')} from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [estado.id])\n          for (const f of camposDeTipo(view)) {\n            const esp = estado.preenchidos[f.column]\n            if (esp) expect.soft(conferirNoBanco(f, esp, linha[f.column]), 'campo depois da edição').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'crud_exclusao') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          const marcadorCampo = campoMarcador(view)!\n          const contar = async () => Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n          const antes = await contar()\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const linha = await acharLinha(page, estado.marcador)\n          expect(linha, `a linha \"${estado.marcador}\" aparece na lista`).not.toBeNull()\n          await linha!.locator('button[title=\"Excluir\"], a[title=\"Excluir\"]').first().click()\n          await confirmarExclusao(page)\n          await expect.poll(async () => (await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [estado.marcador]))[0].n, { message: 'o registro some do banco', timeout: 15_000 }).toBe(0)\n          expect(await contar(), 'só o registro criado pelo teste foi excluído').toBe(antes - 1)\n          gravarEstado(view.slug, undefined)\n        })\n      }\n\n      // --- segurança: derivada da configuração de acesso do projeto (só com o tipo \"seguranca\"; cria usuários e grupos temporários e os apaga) ---\n\n      if (t.kind === 'seg_tabela') {\n        test(t.title, async ({ page }) => {\n          const tp = view.tablePerms ?? { create: true, update: true, delete: true }\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const visiveis = (loc: Locator) => loc.locator('visible=true').count()\n          expect((await visiveis(page.getByRole('link', { name: 'Novo Registro' }))) > 0, `\"Novo Registro\" visível (criar ${tp.create ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.create)\n          const linhas = (await linhasDoGrid(page)).length\n          test.skip(linhas === 0, 'a lista está vazia: sem linhas não há ícones de editar e excluir para conferir')\n          expect((await visiveis(page.locator('main [title=\"Editar\"]'))) > 0, `ícone Editar visível (editar ${tp.update ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.update)\n          expect((await visiveis(page.locator('main [title=\"Excluir\"]'))) > 0, `ícone Excluir visível (excluir ${tp.delete ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.delete)\n        })\n      }\n\n      if (t.kind === 'seg_nivel_nenhum' || t.kind === 'seg_nivel_leitura') {\n        const nivel = t.kind === 'seg_nivel_nenhum' ? 'none' : 'read'\n        test(t.title, async ({ browser }) => {\n          const auth = manifest.auth!\n          const u = await criarUsuarioTemporario(auth, { nivel: { viewSlug: view.slug, nivel } })\n          const marcadorCampo = campoMarcador(view)\n          const marcador = `${RODADA}-forcado`\n          const ctx = await browser.newContext({ baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR', viewport: { width: 1280, height: 800 } })\n          try {\n            const pag = await ctx.newPage()\n            await entrarComo(pag, u.email, u.senha)\n            const menu = (await pag.locator('aside nav a[href^=\"/\"]').evaluateAll(as => as.map(a => (a as HTMLAnchorElement).getAttribute('href')))) as string[]\n            await abrir(pag, view.path)\n            if (nivel === 'none') {\n              expect(menu, 'o menu do grupo sem acesso não lista a tela').not.toContain(view.path)\n              expect(await pag.locator('thead th').count(), 'a tela bloqueada não mostra a lista').toBe(0)\n              expect(await pag.getByText(/TOTAL:\\s*\\d+/i).count(), 'a tela bloqueada não mostra o total').toBe(0)\n              await abrir(pag, `${view.path}/new`)\n              if (marcadorCampo) expect(await pag.locator(`[name=\"${marcadorCampo.column}\"]`).locator('visible=true').count(), 'o formulário não abre pelo endereço').toBe(0)\n            } else {\n              expect(menu, 'o menu do grupo de leitura lista a tela').toContain(view.path)\n              await aguardarLista(pag)\n              expect(await totalMostrado(pag), 'a lista abre e mostra o total').not.toBeNull()\n              expect(await pag.getByRole('link', { name: 'Novo Registro' }).locator('visible=true').count(), '\"Novo Registro\" escondido na leitura').toBe(0)\n              expect(await pag.locator('main [title=\"Editar\"]').locator('visible=true').count(), 'ícone Editar escondido na leitura').toBe(0)\n              expect(await pag.locator('main [title=\"Excluir\"]').locator('visible=true').count(), 'ícone Excluir escondido na leitura').toBe(0)\n              // o servidor recusa gravar mesmo se a pessoa forçar o endereço do formulário\n              if (marcadorCampo) {\n                await abrir(pag, `${view.path}/new`)\n                const campo = pag.locator(`[name=\"${marcadorCampo.column}\"]`).first()\n                if ((await campo.count()) && (await campo.isEnabled())) {\n                  await campo.fill(marcador)\n                  const criar = pag.getByRole('button', { name: 'Criar Registro' }).first()\n                  if (await criar.count()) await criar.click()\n                  await pag.waitForTimeout(1500)\n                }\n                const criados = Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n)\n                if (criados > 0) await consultar(`delete from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]).catch(() => {})\n                expect(criados, 'o servidor aceitou gravar com acesso só de leitura').toBe(0)\n              }\n            }\n          } finally {\n            await ctx.close()\n            await removerUsuarioTemporario(auth, u)\n          }\n        })\n      }\n\n      if (t.kind === 'seg_linha') {\n        const regra = regraDeLinha(view)!\n        test(t.title, async ({ browser }) => {\n          const auth = manifest.auth!\n          const u = await criarUsuarioTemporario(auth, { grupoSemRestricao: true })\n          const marcadorCampo = campoMarcador(view)\n          const ctx = await browser.newContext({ baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR', viewport: { width: 1280, height: 800 } })\n          try {\n            // linhas que a regra deixa este usuário ver: as que têm, na coluna da regra, o valor dele (sem o dado, a regra nega tudo)\n            const valor = await valorDaRegra(auth, u.id, regra.source, regra.attr)\n            const esperado = async () => valor === null ? 0 : Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${regra.column}\"::text = $1`, [valor]))[0].n)\n            const noBanco = Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n            const pag = await ctx.newPage()\n            await entrarComo(pag, u.email, u.senha)\n            await abrir(pag, view.path)\n            await aguardarLista(pag)\n            expect(await pag.locator('thead th').count(), 'a lista abriu para o usuário temporário (um grupo sem restrição de tela)').toBeGreaterThan(0)\n            expect(await totalOuZero(pag), `o usuário temporário (fora da exceção) vê só as linhas da regra; a tabela tem ${noBanco}`).toBe(await esperado())\n            if (noBanco > 0) expect(await totalOuZero(pag), 'a regra esconde as linhas de outras pessoas').toBeLessThan(noBanco)\n\n            // com a regra apontando para quem criou o registro: o que o usuário cria, ele passa a ver\n            if (/^(criado_por|created_by)$/i.test(regra.column) && regra.source === 'user.attr' && marcadorCampo) {\n              const antes = await esperado()\n              const marcador = caber(`${RODADA}-linha`, (await limitesDaTabela(view.table))[marcadorCampo.column])\n              await abrir(pag, `${view.path}/new`)\n              const limites = await limitesDaTabela(view.table)\n              const naoPreenchidos: string[] = []\n              let n = 0\n              for (const f of camposDeTipo(view).filter(x => !x.readOnly)) {\n                const p = await preencherCampo(pag, f, ++n, limites, f.column === marcadorCampo.column ? marcador : undefined)\n                if (!p && f.required) naoPreenchidos.push(f.label)\n              }\n              if (process.env.E2E_DEBUG && naoPreenchidos.length) console.log(`[seg_linha ${view.slug}] não preenchidos: ${naoPreenchidos.join(', ')} · url ${pag.url()}`)\n              test.skip(naoPreenchidos.length > 0, `campo(s) obrigatório(s) que o motor ainda não sabe preencher: ${naoPreenchidos.join(', ')}`)\n              await pag.getByRole('button', { name: 'Criar Registro' }).first().click()\n              await expect.poll(async () => Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n), { timeout: 15_000 }).toBe(1)\n              await abrir(pag, view.path)\n              await aguardarLista(pag)\n              expect(await pag.locator('thead th').count(), 'a lista abriu depois do cadastro').toBeGreaterThan(0)\n              expect(await totalOuZero(pag), 'o registro criado pelo usuário aparece para ele').toBe(antes + 1)\n              expect(await totalOuZero(pag), 'e continua sem ver as linhas de outras pessoas').toBeLessThan(noBanco + 1)\n            }\n          } finally {\n            await ctx.close()\n            // o que o usuário temporário criou sai antes dele (a auditoria aponta para o usuário)\n            if (marcadorCampo) await consultar(`delete from \"${view.table}\" where \"${marcadorCampo.column}\"::text like $1`, [PREFIXO_E2E + '%']).catch(() => {})\n            await removerUsuarioTemporario(auth, u)\n          }\n        })\n      }\n    }\n  })\n}\n",
 "src/lib/testing/plan.ts": "import type { ManifestAuth, ManifestField, ManifestRowRule, ManifestView } from './manifestTypes'\n\n/**\n * Plano de testes de um caso de uso: a lista do que será conferido, derivada do manifesto. É a ÚNICA fonte: o painel da IDE mostra este plano\n * antes de rodar e o teste do Playwright (e2e/dynamic) gera exatamente estes testes, com estes nomes. Sem dependências: o e2e também a importa.\n *\n * Todas as regras daqui só LEEM dados: nenhuma grava no banco (o cadastro com dados gerados entra depois, junto com o banco de teste do cliente).\n */\nexport type PlannedKind =\n  | 'abre' | 'lista' | 'formulario' | 'mascara' | 'obrigatorios'\n  | 'grid_total' | 'grid_ordenacao' | 'grid_filtro' | 'exportacao'\n  | 'grid_paginacao' | 'filtro_opcoes' | 'visualizar' | 'exportacao_filtrada' | 'exportacao_marcadas' | 'central_downloads'\n  | 'botoes' | 'campos_tipos' | 'abas'\n  | 'crud_cadastro' | 'crud_reabrir' | 'crud_edicao' | 'crud_exclusao'\n  | 'seg_tabela' | 'seg_nivel_nenhum' | 'seg_nivel_leitura' | 'seg_linha'\n  | 'filtros_tela' | 'tipo_galeria' | 'tipo_kanban' | 'tipo_fluxo' | 'tipo_timeline' | 'tipo_gantt' | 'tipo_agenda' | 'tipo_mapa_mental' | 'tipo_mapa' | 'tipo_bi'\n\nexport interface PlannedTest {\n  kind: PlannedKind\n  /** nome do teste (é o nome que o Playwright reporta: o painel casa o resultado por ele) */\n  title: string\n  /** coluna, quando o teste é de um campo (máscara, ordenação, filtro) */\n  field?: string\n  /** formato, quando é de exportação (csv, json, xlsx) */\n  format?: string\n  /** rótulo do campo e máscara (entram no texto traduzido do teste) */\n  label?: string\n  mask?: string\n}\n\nexport type PlanLang = 'pt' | 'en' | 'es'\n\n/** Tipos de teste: funcional só LÊ dados; integração GRAVA (cadastro, edição e exclusão com dados gerados) e exige um banco de teste. */\nexport type TestType = 'funcional' | 'integracao' | 'seguranca'\nexport interface PlanOptions {\n  types?: TestType[]\n  /** configuração de login do projeto (manifest.auth): os testes de segurança por grupo e por linha dependem dela */\n  auth?: ManifestAuth\n}\n\n/**\n * Texto do teste no idioma da tela. O `title` (português) é o NOME do teste para o Playwright e a chave dos resultados e do histórico: não muda\n * com o idioma. Só o que aparece na tela (painel, relatório, comparativo) passa por aqui.\n */\nconst PLAN_TEXT: Record<Exclude<PlanLang, 'pt'>, Record<string, (p: PlannedTest) => string>> = {\n  en: {\n    abre: () => 'the screen opens without errors and shows the use case title',\n    lista: () => 'list: the use case filters and columns are on the screen',\n    formulario: () => 'new form: the fields exist, with required and read-only as configured',\n    mascara: p => `mask of \"${p.label}\" (${p.mask}) formats what is typed`,\n    obrigatorios: () => 'required fields: saving the empty form does not create a record',\n    grid_total: () => 'grid: the total shown equals the database total',\n    grid_ordenacao: p => `grid: sort by \"${p.label}\" in both directions`,\n    grid_filtro: p => `filter by \"${p.label}\": filters the rows and the Clear button undoes it`,\n    seg_tabela: () => 'table permissions: New Record, Edit and Delete appear only as Studio allows',\n    seg_nivel_nenhum: () => 'group access \"none\": the screen disappears from the menu and does not open by address',\n    seg_nivel_leitura: () => 'group access \"read\": opens and shows the data, but does not allow creating, editing or deleting',\n    seg_linha: () => 'row rule: whoever is not in the exception only sees the rows the rule allows',\n    crud_cadastro: () => 'registration: filling in generated data and saving writes everything to the database',\n    crud_reabrir: () => 'registration: reopening the record shows what was saved',\n    crud_edicao: () => 'edit: changing and saving writes only the change',\n    crud_exclusao: () => 'deletion: deleting from the list removes the record',\n    grid_paginacao: () => 'grid: pagination respects the chosen page size',\n    filtro_opcoes: p => `filter by \"${p.label}\" option: only the rows of the option appear and Clear undoes it`,\n    visualizar: () => 'View: opens the record read-only, without a save button',\n    exportacao_filtrada: () => 'export: only what is filtered on the screen',\n    exportacao_marcadas: () => 'export: only the checked rows',\n    central_downloads: () => 'Downloads Center: lists the export and downloads the file',\n    botoes: () => 'buttons: the buttons configured in Studio are on the screen',\n    campos_tipos: () => 'form: each field uses the configured component (text, number, date, options)',\n    abas: () => 'tabs: the detail tabs configured in Studio are in the form',\n    filtros_tela: () => 'filters: all the use case filters are on the screen',\n    tipo_galeria: () => 'gallery: one card per record, equal to the database',\n    tipo_kanban: () => 'kanban: the cards (plus those still to load) add up to the database total',\n    tipo_fluxo: () => 'flow: the diagram opens and the number of steps equals the database',\n    tipo_timeline: () => 'timeline: the screen opens with data refresh and no error',\n    tipo_gantt: () => 'gantt: Today button, sizes and row actions',\n    tipo_agenda: () => 'calendar: month, week and day show different views',\n    tipo_mapa_mental: () => 'mind map: the number of records equals the database',\n    tipo_mapa: () => 'map: the map opens and the total with coordinates equals the database',\n    tipo_bi: () => 'BI: the dashboard opens, refreshes and shows data',\n    exportacao: p => `${FORMATOS_EXPORTACAO[p.format || ''] || p.format} export: ${({ csv: 'header with the grid columns and one line per record', json: 'one item per record', xlsx: 'valid .xlsx file' } as Record<string, string>)[p.format || ''] || ''}`,\n  },\n  es: {\n    abre: () => 'la pantalla abre sin errores y muestra el título del caso de uso',\n    lista: () => 'lista: los filtros y las columnas del caso de uso están en la pantalla',\n    formulario: () => 'formulario nuevo: los campos existen, con obligatorio y solo lectura como configurado',\n    mascara: p => `la máscara de \"${p.label}\" (${p.mask}) formatea lo que se escribe`,\n    obrigatorios: () => 'obligatorios: guardar el formulario vacío no crea registro',\n    grid_total: () => 'grid: el total mostrado es igual al total de la base de datos',\n    grid_ordenacao: p => `grid: ordenar por \"${p.label}\" en ambos sentidos`,\n    grid_filtro: p => `filtro de \"${p.label}\": filtra las filas y el botón Limpiar lo deshace`,\n    seg_tabela: () => 'permisos de la tabla: Nuevo Registro, Editar y Eliminar aparecen solo como Studio lo permite',\n    seg_nivel_nenhum: () => 'acceso \"ninguno\" al grupo: la pantalla desaparece del menú y no abre por la dirección',\n    seg_nivel_leitura: () => 'acceso \"lectura\" al grupo: abre y muestra los datos, pero no permite crear, editar ni eliminar',\n    seg_linha: () => 'regla por fila: quien no está en la excepción solo ve las filas que la regla permite',\n    crud_cadastro: () => 'registro: llenar con datos generados y guardar graba todo en la base de datos',\n    crud_reabrir: () => 'registro: reabrir el registro muestra lo que se guardó',\n    crud_edicao: () => 'edición: cambiar y guardar graba solo el cambio',\n    crud_exclusao: () => 'eliminación: eliminar desde la lista quita el registro',\n    grid_paginacao: () => 'grid: la paginación respeta el tamaño de página elegido',\n    filtro_opcoes: p => `filtro de \"${p.label}\" por opción: solo aparecen las filas de la opción y Limpiar lo deshace`,\n    visualizar: () => 'Visualizar: abre el registro solo lectura, sin botón de guardar',\n    exportacao_filtrada: () => 'exportación: solo lo que está filtrado en la pantalla',\n    exportacao_marcadas: () => 'exportación: solo las filas marcadas',\n    central_downloads: () => 'Centro de descargas: lista la exportación y descarga el archivo',\n    botoes: () => 'botones: los botones configurados en Studio están en la pantalla',\n    campos_tipos: () => 'formulario: cada campo usa el componente configurado (texto, número, fecha, opciones)',\n    abas: () => 'pestañas: las pestañas de detalle configuradas en Studio están en el formulario',\n    filtros_tela: () => 'filtros: todos los filtros del caso de uso están en la pantalla',\n    tipo_galeria: () => 'galería: una tarjeta por registro, igual a la base de datos',\n    tipo_kanban: () => 'kanban: las tarjetas (más las que faltan cargar) suman el total de la base de datos',\n    tipo_fluxo: () => 'flujo: el diagrama abre y el número de etapas es igual a la base de datos',\n    tipo_timeline: () => 'línea de tiempo: la pantalla abre con actualización de datos y sin error',\n    tipo_gantt: () => 'gantt: botón Hoy, tamaños y acciones de las filas',\n    tipo_agenda: () => 'agenda: mes, semana y día muestran vistas distintas',\n    tipo_mapa_mental: () => 'mapa mental: el número de registros es igual a la base de datos',\n    tipo_mapa: () => 'mapa: el mapa abre y el total con coordenadas es igual a la base de datos',\n    tipo_bi: () => 'BI: el panel abre, se actualiza y muestra datos',\n    exportacao: p => `exportación ${FORMATOS_EXPORTACAO[p.format || ''] || p.format}: ${({ csv: 'encabezado con las columnas del grid y una línea por registro', json: 'un elemento por registro', xlsx: 'archivo .xlsx válido' } as Record<string, string>)[p.format || ''] || ''}`,\n  },\n}\n\n/** Texto do teste para mostrar na tela, no idioma pedido (português = o próprio título). */\nexport const planTitle = (p: PlannedTest, lang: PlanLang): string => (lang === 'pt' ? p.title : PLAN_TEXT[lang]?.[p.kind]?.(p) ?? p.title)\n\n/** Gabarito de cada tipo de tela especial (além de \"a tela abre\" e dos filtros): o tipo de tela → a regra que o confere. */\nexport const TIPO_TELA: Record<string, PlannedKind> = {\n  galeria: 'tipo_galeria', kanban: 'tipo_kanban', blueprint: 'tipo_fluxo', timeline: 'tipo_timeline', gantt: 'tipo_gantt',\n  scheduler: 'tipo_agenda', mapa_mental: 'tipo_mapa_mental', map: 'tipo_mapa', analytics: 'tipo_bi',\n}\n/** Tipos de tela com gabarito (lista, formulário, grid, exportação, ou a regra própria do tipo). Os demais (telas de IA) têm só \"a tela abre\". */\nexport const SUPPORTED_LOGIC_TYPES = ['pesquisa_cadastro', ...Object.keys(TIPO_TELA)]\nexport const isSupportedView = (v: Pick<ManifestView, 'logicType'>): boolean => SUPPORTED_LOGIC_TYPES.includes(v.logicType)\n\n/** Nome do grupo de testes de um caso de uso (o \"describe\" do Playwright). */\nexport const describeName = (v: Pick<ManifestView, 'title' | 'slug' | 'logicType'>): string => `${v.title} (${v.slug}) · ${v.logicType}`\n\n/** Só máscaras de padrão fixo (0 = dígito; . - / ( ) e espaço literais). Máscaras numéricas (0.000,00) têm outra regra e não entram aqui. */\nexport const mascaraDePadrao = (m?: string): boolean => !!m && /^[0.\\-/() ]+$/.test(m) && /0{2}/.test(m) && !/^0\\.0+,0+$/.test(m)\n\n/** \"00.000.000/0000-00\" + dígitos → \"11.111.111/1111-11\" (cada 0 consome um dígito; o resto é literal). */\nexport function aplicarMascara(digitos: string, mascara: string): string {\n  let out = ''\n  let i = 0\n  for (const ch of mascara) {\n    if (i >= digitos.length) break\n    if (ch === '0') out += digitos[i++]\n    else out += ch\n  }\n  return out\n}\n\nexport const camposEditaveis = (v: Pick<ManifestView, 'form'>): ManifestField[] => v.form.filter(f => !f.isPrimaryKey)\n\n/** Campo de texto livre (serve para ordenar e filtrar por texto): não é lista de opções, nem fórmula, nem chave. */\nexport const ehTexto = (f: ManifestField): boolean =>\n  /char|text|string/i.test(f.dataType) && !f.options?.length && !f.hasFormula && !f.isPrimaryKey && !/select|sele[cç][aã]o|autocomplete/i.test(f.componentType || '')\n\n/** Campo de data/hora: o app usa o seletor nativo de data e a máscara de texto não se aplica (o tipo do componente no Studio manda sobre a máscara). */\nexport const ehData = (f: ManifestField): boolean => /date|time/i.test(f.dataType) || /data|date|hora/i.test(f.componentType || '')\n\nexport const FORMATOS_EXPORTACAO: Record<string, string> = { csv: 'CSV', json: 'JSON', xlsx: 'Excel' }\n\n/** A tela e os campos usados em cada regra de grid (a mesma escolha vale para o plano e para o teste). */\nexport const campoDeOrdenacao = (v: Pick<ManifestView, 'grid'>): ManifestField | undefined => v.grid.find(ehTexto)\n/** O filtro precisa estar também no grid: é pelas células do grid que o teste confere que as linhas casam com o filtro. */\nexport const campoDeFiltro = (v: Pick<ManifestView, 'filter' | 'grid'>): ManifestField | undefined =>\n  v.filter.find(f => ehTexto(f) && v.grid.some(g => g.column === f.column))\n\n/** Filtro por lista de opções (select) que também está no grid: dá para conferir as linhas pela célula. */\nexport const campoDeFiltroOpcoes = (v: Pick<ManifestView, 'filter' | 'grid'>): ManifestField | undefined =>\n  v.filter.find(f => f.options?.length && v.grid.some(g => g.column === f.column))\n\n/** Campos do formulário que o teste de tipos confere (têm nome no HTML: ficam de fora os calculados por fórmula). */\nexport const camposDeTipo = (v: Pick<ManifestView, 'form'>): ManifestField[] => v.form.filter(f => !f.isPrimaryKey && !f.hasFormula && f.dataType !== 'virtual')\n\nconst TITULO_TIPO: Record<string, string> = {\n  tipo_galeria: 'galeria: um cartão por registro, igual ao banco',\n  tipo_kanban: 'kanban: os cartões (mais os que faltam carregar) somam o total do banco',\n  tipo_fluxo: 'fluxo: o diagrama abre e o total de etapas é igual ao banco',\n  tipo_timeline: 'timeline: a tela abre com atualização de dados e sem erro',\n  tipo_gantt: 'gantt: botão Hoje, tamanhos e ações das linhas',\n  tipo_agenda: 'agenda: mês, semana e dia mostram visões diferentes',\n  tipo_mapa_mental: 'mapa mental: o total de registros é igual ao banco',\n  tipo_mapa: 'mapa: o mapa abre e o total com coordenadas é igual ao banco',\n  tipo_bi: 'BI: o painel abre, atualiza e mostra dados',\n}\n\n/**\n * Campo de texto que identifica o registro criado pelo teste de integração: o primeiro campo de texto livre, editável e sem máscara de padrão.\n * É nele que o motor grava o prefixo \"E2E-\" (a limpeza de sobras só apaga linhas assim) e é por ele que acha a linha no banco.\n */\nexport const campoMarcador = (v: Pick<ManifestView, 'form'>): ManifestField | undefined =>\n  v.form.find(f => !f.isPrimaryKey && !f.readOnly && !f.hasFormula && ehTexto(f) && !mascaraDePadrao(f.mask))\n\n/** Prefixo dos dados gerados pelo teste de integração. */\nexport const PREFIXO_E2E = 'E2E-'\n\n/**\n * Regra por linha que o motor sabe conferir: compara uma coluna com um valor que o motor controla no usuário temporário (id, e-mail, nome ou uma coluna dele).\n * Regras \"related\" (a coluna aponta para outra tabela) ficam de fora por enquanto.\n */\nexport const regraDeLinha = (v: Pick<ManifestView, 'rowPolicy'>): ManifestRowRule | undefined =>\n  v.rowPolicy?.find(r => r.op === 'eq' && (r.source !== 'user.attr' || !!r.attr))\n\n/** Testes de segurança derivados da configuração do projeto (criam usuários e grupos temporários no banco de teste e os apagam no fim). */\nfunction planoSeguranca(v: ManifestView, auth?: ManifestAuth): PlannedTest[] {\n  if (v.logicType !== 'pesquisa_cadastro') return []\n  const out: PlannedTest[] = [{ kind: 'seg_tabela', title: 'permissões da tabela: Novo Registro, Editar e Excluir aparecem só como o Studio permite' }]\n  if (auth?.type === 'database') {\n    if (auth.access) {\n      out.push({ kind: 'seg_nivel_nenhum', title: 'acesso \"nenhum\" ao grupo: a tela some do menu e não abre pelo endereço' })\n      out.push({ kind: 'seg_nivel_leitura', title: 'acesso \"leitura\" ao grupo: abre e mostra os dados, mas não deixa criar, editar nem excluir' })\n    }\n    if (regraDeLinha(v)) out.push({ kind: 'seg_linha', title: 'regra por linha: quem não é da exceção só vê as linhas que a regra permite' })\n  }\n  return out\n}\n\n/** Testes de integração (gravam no banco de teste): cadastro, reabrir, edição e exclusão com dados gerados. Só para Pesquisa + Cadastro com um campo marcador. */\nfunction planoIntegracao(v: ManifestView): PlannedTest[] {\n  if (v.logicType !== 'pesquisa_cadastro' || !campoMarcador(v)) return []\n  return [\n    { kind: 'crud_cadastro', title: 'cadastro: preencher com dados gerados e salvar grava tudo no banco' },\n    { kind: 'crud_reabrir', title: 'cadastro: reabrir o registro mostra o que foi gravado' },\n    { kind: 'crud_edicao', title: 'edição: alterar e salvar grava só a alteração' },\n    { kind: 'crud_exclusao', title: 'exclusão: excluir pela lista remove o registro' },\n  ]\n}\n\nexport function planView(v: ManifestView, opts: PlanOptions = {}): PlannedTest[] {\n  const types = opts.types ?? ['funcional']\n  return [\n    ...(types.includes('funcional') ? planoFuncional(v) : []),\n    ...(types.includes('integracao') ? planoIntegracao(v) : []),\n    ...(types.includes('seguranca') ? planoSeguranca(v, opts.auth) : []),\n  ]\n}\n\nfunction planoFuncional(v: ManifestView): PlannedTest[] {\n  const plano: PlannedTest[] = [{ kind: 'abre', title: 'a tela abre sem erro e mostra o título do caso de uso' }]\n  if (!isSupportedView(v)) return plano\n\n  // telas especiais: o gabarito do tipo + os filtros configurados\n  const tipo = TIPO_TELA[v.logicType]\n  if (tipo) {\n    plano.push({ kind: tipo, title: TITULO_TIPO[tipo] })\n    if (v.filter.length > 0) plano.push({ kind: 'filtros_tela', title: 'filtros: todos os filtros do caso de uso estão na tela' })\n    return plano\n  }\n\n  const editaveis = camposEditaveis(v)\n  plano.push(\n    { kind: 'lista', title: 'lista: os filtros e as colunas do caso de uso estão na tela' },\n    { kind: 'formulario', title: 'formulário novo: os campos existem, com obrigatório e somente leitura como configurado' },\n  )\n  for (const f of editaveis.filter(x => mascaraDePadrao(x.mask) && !ehData(x))) plano.push({ kind: 'mascara', field: f.column, label: f.label, mask: f.mask, title: `máscara de \"${f.label}\" (${f.mask}) formata o que se digita` })\n  if (editaveis.some(f => f.required)) plano.push({ kind: 'obrigatorios', title: 'obrigatórios: salvar o formulário vazio não cria registro' })\n\n  plano.push({ kind: 'grid_total', title: 'grid: o total mostrado é igual ao total do banco' })\n  const ord = campoDeOrdenacao(v)\n  if (ord) plano.push({ kind: 'grid_ordenacao', field: ord.column, label: ord.label, title: `grid: ordenar por \"${ord.label}\" nos dois sentidos` })\n  const fil = campoDeFiltro(v)\n  if (fil) plano.push({ kind: 'grid_filtro', field: fil.column, label: fil.label, title: `filtro de \"${fil.label}\": filtra as linhas e o botão Limpar desfaz` })\n\n  const descr: Record<string, string> = {\n    csv: 'cabeçalho com as colunas do grid e uma linha por registro',\n    json: 'um item por registro',\n    xlsx: 'arquivo .xlsx válido',\n  }\n  for (const fmt of v.exportFormats.map(x => x.toLowerCase()).filter(x => FORMATOS_EXPORTACAO[x])) {\n    plano.push({ kind: 'exportacao', format: fmt, title: `exportação ${FORMATOS_EXPORTACAO[fmt]}: ${descr[fmt]}` })\n  }\n\n  // fase 3 (só leitura): paginação, filtro por opção, Visualizar, exportação filtrada/marcada, Central de Downloads, botões, tipos de campo e abas\n  plano.push({ kind: 'grid_paginacao', title: 'grid: a paginação respeita o tamanho de página escolhido' })\n  const opc = campoDeFiltroOpcoes(v)\n  if (opc) plano.push({ kind: 'filtro_opcoes', field: opc.column, label: opc.label, title: `filtro de \"${opc.label}\" por opção: só traz as linhas da opção e o botão Limpar desfaz` })\n  plano.push({ kind: 'visualizar', title: 'Visualizar: abre o registro só para leitura, sem botão de gravar' })\n  if (v.exportFormats.some(x => ['csv', 'json'].includes(x.toLowerCase()))) {\n    if (fil) plano.push({ kind: 'exportacao_filtrada', title: 'exportação: só o que está filtrado na tela' })\n    plano.push({ kind: 'exportacao_marcadas', title: 'exportação: só as linhas marcadas' })\n    if (v.exportFormats.some(x => x.toLowerCase() === 'csv')) plano.push({ kind: 'central_downloads', title: 'Central de Downloads: lista a exportação e baixa o arquivo' })\n  }\n  if (v.buttons.length > 0) plano.push({ kind: 'botoes', title: 'botões: os botões configurados no Studio estão na tela' })\n  if (camposDeTipo(v).length > 0) plano.push({ kind: 'campos_tipos', title: 'formulário: cada campo usa o componente configurado (texto, número, data, opções)' })\n  if (v.details.length > 0) plano.push({ kind: 'abas', title: 'abas: as abas de detalhe configuradas no Studio estão no formulário' })\n  return plano\n}\n",
 "src/lib/testing/manifestTypes.ts": "/**\n * Tipos do manifesto de testes (sem dependências: o teste do Playwright também os importa).\n * O manifesto descreve cada caso de uso como o dev o configurou no Studio. Ver manifest.ts.\n */\nexport const MANIFEST_VERSION = 1\n\n/**\n * Como o app exportado faz o login e controla o acesso. Com isto o motor cria sozinho o usuário de teste no banco de teste, para qualquer projeto.\n * `type`: database (tabela de usuários do próprio banco), none (app sem login) ou outro (managed, ldap...: ainda sem suporte nos testes).\n */\nexport interface ManifestAuth {\n  type: string\n  usersTable?: string\n  usersPk?: string\n  emailColumn?: string\n  passwordColumn?: string\n  nameColumn?: string\n  hash?: string\n  /** só quando a gestão de acesso está ligada: grupos, vínculo usuário-grupo e permissões por tela */\n  access?: {\n    groupsTable: string\n    groupsPk: string\n    groupsNameColumn: string\n    link: { kind: 'column'; column: string } | { kind: 'table'; table: string; userColumn: string; roleColumn: string }\n    permsTable: string\n    permsRoleColumn: string\n    permsViewColumn: string\n    permsLevelColumn: string\n  }\n}\n\nexport interface ManifestOption { value: string; label: string }\n\nexport interface ManifestField {\n  /** nome da coluna no banco (é também o `name` do campo no app exportado) */\n  column: string\n  label: string\n  dataType: string\n  /** tipo de componente escolhido no Studio (Seleção, Numérico, Data/Hora, Autocomplete...) */\n  componentType?: string\n  /** máscara de entrada do Studio (ex.: 00.000.000/0000-00) */\n  mask?: string\n  /** obrigatório por configuração do Studio OU por ser coluna NOT NULL sem valor padrão */\n  required: boolean\n  readOnly: boolean\n  isPrimaryKey: boolean\n  hasFormula: boolean\n  options?: ManifestOption[]\n}\n\nexport interface ManifestButton { id: string; label: string; actionType: string; placement?: string }\n\nexport interface ManifestDetail {\n  table: string\n  label: string\n  foreignKey: string\n  displayMode: 'tab' | 'inline'\n  fields: ManifestField[]\n  subDetails: Array<{ table: string; label: string; foreignKey: string; fields: ManifestField[] }>\n}\n\n/** Regra de acesso por linha do Studio (a tabela só mostra ao usuário as linhas em que `column` é igual ao valor dele), com a exceção por valor ou grupo. */\nexport interface ManifestRowRule {\n  column: string\n  op: 'eq' | 'in' | 'related'\n  source: 'user.email' | 'user.name' | 'user.attr'\n  attr?: string\n  bypass?: { source: string; attr?: string; values: string[] }\n}\n\nexport interface ManifestView {\n  slug: string\n  path: string\n  title: string\n  logicType: string\n  table: string\n  primaryKey: string\n  displayType: string\n  actionInterface: string\n  /** o que a tabela permite ao usuário final (Dados & Schemas): criar, editar e excluir */\n  tablePerms?: { create: boolean; update: boolean; delete: boolean }\n  /** regras por linha da tabela; ausente = todos veem todas as linhas */\n  rowPolicy?: ManifestRowRule[]\n  filter: ManifestField[]\n  grid: ManifestField[]\n  form: ManifestField[]\n  buttons: ManifestButton[]\n  exportFormats: string[]\n  details: ManifestDetail[]\n}\n\nexport interface TestManifest {\n  version: number\n  generatedAt: string\n  project: { id: string; name: string; slug: string }\n  auth?: ManifestAuth\n  dbStack: string\n  views: ManifestView[]\n}\n",
 "src/lib/testing/results.ts": "/**\n * Resultado dos testes, como o relator do e2e (e2e/dynamic/ide-reporter.ts) o envia: uma linha por evento, começando com MB_PREFIX e seguida de JSON.\n * O painel da IDE lê a saída do Playwright, separa estas linhas e atualiza a tela a cada teste que começa e termina.\n */\nexport const MB_PREFIX = '@@MB@@'\n\nexport type TestStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped'\n\nexport interface TestEvent {\n  /** begin = começou · end = terminou · done = a rodada acabou */\n  t: 'begin' | 'end' | 'done'\n  /** nome do grupo (caso de uso) e do teste, como em describeName/planView */\n  group?: string\n  title?: string\n  status?: TestStatus\n  ms?: number\n  /** primeiras linhas do erro, quando falhou */\n  error?: string\n  /** arquivos de evidência da falha (captura da tela e vídeo), quando o motor os gravou */\n  shot?: string\n  video?: string\n  /** só em done */\n  total?: number\n  passed?: number\n  failed?: number\n  skipped?: number\n}\n\n/** Uma linha da saída do Playwright → evento, ou null se não for uma linha do relator. */\nexport function parseTestEvent(line: string): TestEvent | null {\n  const i = line.indexOf(MB_PREFIX)\n  if (i < 0) return null\n  try {\n    const ev = JSON.parse(line.slice(i + MB_PREFIX.length)) as TestEvent\n    return ev && (ev.t === 'begin' || ev.t === 'end' || ev.t === 'done') ? ev : null\n  } catch {\n    return null\n  }\n}\n\n/** Playwright: passed/failed/timedOut/skipped/interrupted → status do painel. */\nexport function statusFromPlaywright(s: string): TestStatus {\n  if (s === 'passed') return 'passed'\n  if (s === 'skipped') return 'skipped'\n  return 'failed' // failed, timedOut, interrupted\n}\n\nexport const eventLine = (ev: TestEvent): string => MB_PREFIX + JSON.stringify(ev)\n"
}
